begin;

insert into hadith (id, collection_id, chapter_id, number_in_book, kind, arabic, translation_en, narrator_ar, narrator_en, grade_ar, reference_ar, reference_en, reference_ur, full_ref_ar, explanation_ar, benefits_ar, word_meanings_ar, source, source_ref, daily_ok, review_note, deleted) values
(20241, 2, 201, 241, 'hadith', 'وعنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «كل أمتي معافًى إلا المجاهرين، وإن من المجاهرة أن يعمل الرجل بالليل عملاً، ثم يصبح وقد ستره الله عليه فيقول: يا فلان عملت البارحة كذا وكذا، وقد بات يستره ربه، ويصبح يكشف ستر الله عنه».', 'Messenger of Allah (ﷺ) said, "Every one of my followers will be forgiven except those who expose (openly) their wrongdoings. An example of this is that of a man who commits a sin at night which Allah has covered for him, and in the morning, he would say (to people): "I committed such and such sin last night,'' while Allah had kept it a secret. During the night Allah has covered it up but in the morning he tears up the cover provided by Allah Himself.".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 241', 'Riyad as-Salihin 241', 'ریاض الصالحین 241', 'متفق عليه', 'بَيَّنَ النبيُّ صلى الله عليه وسلم أنَّ المسلمَ المُذنبَ يُرجى له عفوُ الله ومغفرتُه، إلا المعلن بالمعصية تفاخُرًا ووقاحةً فلا يَستحقُّ العفو؛ حيث يَعملُ المعصيةَ بالليل، ثم يُصبِحُ وقد ستره الله، فيُحدِّث غَيرَه بأنه فَعَلَ المعصيةَ الفلانية أمس، وقد باتَ يَستُرُه ربُّه، ويُصبحُ يَكشِفُ سِتْرَ الله عليه!!', 'قُبح المجاهرة بالمعصية بعد سِتْرِ الله تعالى عليه.
في المجاهرة بالمعصية إشاعةُ الفاحشةِ بين المؤمنين.
مَن سَتَرَه الله في الدنيا سَتَرَه في الآخرة، وهذا من سعة رحمة الله تعالى بعباده.
مَن ابتُلي بمعصية عليه أن يَسْتُرَ على نفسِه وأن يَتوبَ إلى الله.
عِظم ذنب المجاهرين الذين يتقصدون إظهار المعاصي، ويُفوِّتون على أنفسهم المعافاة.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3756', false),
(20242, 2, 201, 242, 'hadith', 'وعنه النبي صلى الله عليه وسلم قال: «إذا زنت الأمة فتبين زناها فليجلدها الحد، ولا يثرب عليها، ثم إن زنت الثانية فليجلدها الحد ولا يثرب عليها، ثم إن زنت الثالثة فليبعها ولو بحبل من شعر» ((متفق عليه)) . (15)', 'The Prophet (ﷺ) said, "When a slave-girl commits fornication and this fact of fornication has become evident, she must be given the penalty of (fifty) lashes without hurling reproaches at her; if she does it again, she must be given the penalty but she should not be rebuked. If she does it for the third time, he should sell her, even for a rope woven from hair (i.e., something worthless)"..', null, 'Abu Hurairah (May Allah bepleased with him)', null, 'رياض الصالحين 242', 'Riyad as-Salihin 242', 'ریاض الصالحین 242', null, null, null, null, 'sunnah.com', null, false, null, false),
(20243, 2, 201, 243, 'hadith', 'وعنه قال: أتى النبي صلى الله عليه وسلم برجل قد شرب خمرًا قال: "اضربوه" قال أبو هريرة : فمنا الضارب بيده، والضارب بنعله، والضارب بثوبه. فلما انصرف قال بعض القوم: أخزاك الله قال: "لا تقولوا هكذا لا تعينوا عليه الشيطان".', 'A man who had drunk wine was brought to the Prophet (ﷺ) and he asked us to beat him; some struck him with their hands, some with their garments (making a whip) and some with their sandals. When he (the drunkard) had gone, some of the people said: "May Allah disgrace you!" He (the Prophet (ﷺ)) said, "Do not say so. Do not help the devil against him"..', null, 'Abu Hurairah (May Allah bepleased with him)', 'صحيح', 'رياض الصالحين 243', 'Riyad as-Salihin 243', 'ریاض الصالحین 243', 'رواه البخاري', 'معنى الحديث: أن الصحابة -رضي الله تعالى عنهم- جاءوا إلى النبي صلى الله عليه وسلم برجل قد شرب الخمر، فأمر النبي صلى الله عليه وسلم بضربه فضربه الصحابة، فبعضهم ضربه بيده دون استعمال أداة أخرى من أدوات الضرب، ومنهم الضارب بنعله وهذا من التنكيل به ومنهم الضارب بثوبه، ولم يستعملوا السوط الذي هو أداة الحد في الضرب، وجاء في رواية أنه أمر عشرين رجلًا فضربه كل رجل جلدتين بالجريد والنعال، وهذا يفسر أن الجلد أربعين، وما جاء عن الخلفاء الراشدين من زيادة على ذلك فهو تعزير راجع للإمام.
ثم لما فرغ الناس من ضربه، دعا عليه بعضهم بقوله : " أخزاك الله" أي: دعا عليه بالخزي، وهو الذل والمهانة والفضيحة بين الناس، فقال النبي صلى الله عليه وسلم : "لا تقولوا له هكذا لا تعينوا عليه الشيطان"؛ لأنهم إذا دعوا عليه بالخزي ربما استجيب لهم، فبلغ الشيطان مأربه، ونال مقصده ومطلبه، وحتى لا ينفر العاصي وقد حد.', 'حصول حد شارب الخمر بالضرب باليد وأطراف الثوب والجريد والنعال.
الحدود زواجر جوابر فمن أقيم عليه الحد كان كفارة له.
أسلوب النبي -صلى الله عليه وسلم- في توجيه العصاة بعدم تعييرهم أو سبهم، مما يجعل ذلك أدعى إلى استجلابهم إلى ترك المعاصي.
لا ينبغي للمسلم أن يكون عوناً للشيطان على أخيه المسلم إذا فرط في حق من الحقوق.
على المسلمين أن يحرصوا على رد العصاة إلى جانب الحق و الصواب.
مرتكب الكبيرة لا يكفر بها لثبوت النهي عن لعنه، والأمر بالدعاء له.
فيه دليل على أن الإنسان إذا فعل ذنبًا وعوقب عليه في الدنيا، فإنه لا يجوز لنا أن ندعو عليه بالخزي والعار، بل نسأل الله له الهداية، ونسأل الله له المغفرة.
فيه تحريم شرب الخمر وأن من شربها عوقب.
فيه الرفع إلى ولي الأمر إذا اقتضى الأمر ذلك.
الدعاء للعاصي بعد إقامة الحد علية بالتوفيق والنجاة من الخذلان.', 'أخزاك الله : أهانك وأذلك.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3262', false),
(20244, 2, 201, 244, 'hadith', 'عن ابن عمر رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال: «المسلم أخو المسلم لا يظلمه ولا يسلمه. من كان في حاجة أخيه كان الله في حاجته، ومن فرج عن مسلم كربة فرج الله عنه بها كربة من كرب يوم القيامة، ومن ستر مسلمًا ستره الله يوم القيامة».', 'Messenger of Allah (ﷺ) said, "A Muslim is a brother of (another) Muslim, he neither wrongs him nor does hand him over to one who does him wrong. If anyone fulfills his brother''s needs, Allah will fulfill his needs; if one relieves a Muslim of his troubles, Allah will relieve his troubles on the Day of Resurrection; and if anyone covers up a Muslim (his sins), Allah will cover him up (his sins) on the Resurrection Day"..', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah bepleased with them)', 'صحيح', 'رياض الصالحين 244', 'Riyad as-Salihin 244', 'ریاض الصالحین 244', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20245, 2, 201, 245, 'hadith', 'عن أبي هريرة رضي الله عنه، عن النبي صلى الله عليه وسلم قال: «من نفس عن مؤمن كربة من كرب الدنيا، نفس الله عنه كربة من كرب يوم القيامة، ومن يسر على معسر يسر الله عليه في الدنيا والآخرة، ومن ستر مسلمًا ستره الله في الدنيا والآخرة، والله في عون العبد ما كان العبد في عون أخيه، ومن سلك طريقًا يلتمس فيه علمًا سهل الله له طريقًا إلى الجنة. وما اجتمع قوم في بيت من بيوت الله تعالى، يتلون كتاب الله، ويتدارسونه بينهم إلا نزلت عليهم السكينة، وغشيتهم الرحمة، وحفتهم الملائكة، وذكرهم الله فيمن عنده. ومن بطأ به عمله لم يسرع به نسبه».', 'The Prophet (ﷺ) said, "He who removes from a believer one of his difficulties of this world, Allah will remove one of his troubles on the Day of Resurrection; and he who finds relief for a hard-pressed person, Allah will make things easy for him on the Day of Resurrection; he who covers up (the faults and sins) of a Muslim, Allah will cover up (his faults and sins) in this world and in the Hereafter. Allah supports His slave as long as the slave is supportive of his brother; and he who treads the path in search of knowledge, Allah makes that path easy, leading to Jannah for him; the people who assemble in one of the houses of Allah, reciting the Book of Allah, learning it and teaching, there descends upon them the tranquillity, and mercy covers them, the angels flock around them, and Allah mentions them in the presence of those near Him; and he who lags behind in doing good deeds, his noble lineage will not make him go ahead."', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah bepleased with him)', 'صحيح', 'رياض الصالحين 245', 'Riyad as-Salihin 245', 'ریاض الصالحین 245', 'رواه مسلم', 'بَيَّنَ النبيُّ صلى الله عليه وسلم أنَّ جَزاء المسلم عند الله مِن جِنْس ما يَعمله المسلم مع المسلمين؛ فمَن نفَّس وفرَّج وأزال وكَشَفَ عن مؤمنٍ كُربةً وشدة من كُرَب الدنيا، جازاه الله بأن ينفَّس عنه كربةً من كرب يوم القيامة.

ومَن يَسَّر على معسرٍ وسهَّل عليه وأزال عسرته، يسَّر الله عليه في الدنيا والآخرة. 

ومَن ستر مسلمًا كأن اطّلع منه على ما لا ينبغي إظهاره من الزّلات والعَثَرات، ستره الله في الدنيا والآخرة. 

والله يكون مُعينًا لِعَبدِه، ما كان العبد سائرًا في إعانة أخيه في مصالحه الدينية والدنيوية، والإعانة تكون بالدعاء والبدن والمال وغير ذلك. 

ومن مشى إلى تحصيل علمٍ شرعيٍ، قاصدًا به وجه الله تعالى؛ سهَّل الله له به طريقًا إلى الجنة. 

وما اجتمع قومٌ في بيتٍ من بيوت الله، يتلون كتاب الله ويتدارسونه بينهم، إلا نزلت عليهم الطمأنينة والوقار، وغطتهم وعمَّتهم رحمة الله، وحفَّتْهم الملائكة، وأثنى الله عليهم في المقرَّبين عنده، وكفى شرفًا ذِكرُ اللهِ العبدَ في الملأ الأعلى. 

ومَن كان عمله ناقصًا، لم يُلْحِقْه بمرتبة أصحاب الأعمال، فينبغي ألا يَتَّكل على شرف النسب وفضيلة الآباء ويُقَصّر في العمل.', 'قال ابن دقيق العيد: هذا حديث عظيم، جامع لأنواع من العلوم والقواعد والآداب، فيه فضل قضاء حوائج المسلمين ونفعهم بما يتيسر، مِن علم، أو مال، أو معاونة، أو إشارة بمصلحة، أو نصيحة، أو غير ذلك.
الترغيب في التيسير على المعسر.
الحث على عون العبد المسلم، وأن الله تعالى يُعين المعين حسب إعانته لأخيه.
مِن سِتْر المسلم: عدمُ تتبُّع عوراته، وقد رُوي عن بعض السلف أنه قال: أدركت قومًا لم يكن لهم عيوب، فذكروا عيوبَ الناس، فَذَكَر الناسُ لهم عيوبًا، وأدركت قومًا كانت لهم عيوب، فَكَفُّوا عن عيوب الناس، فنُسِيت عيوبُهم.
ليس من لوازم الستر على الناس ترك المنكر وعدم تغييره، بل يُغَيِّر ويَسْتُر، وهذا في حقِّ مَن لا يُعرَف بالفساد والتَّمَادِيْ في الطغيان، وأما من عُرِف بذلك فإنه لا يُستحب الستر عليه، بل يرفع أمره إلى مَن له الولاية، إذا لم يخَفْ مِن ذلك مفسدة؛ وذلك لأن الستر عليه يُغْرِيْهِ على الفساد، ويُجَرِّئهُ على أذية العباد، ويُجرّئ غيره من أهل الشر والعناد.
الحث على طلب العلم وتلاوة القرآن وتدارسه.
قال النووي: في هذا دليل لفضل الاجتماع على تلاوة القرآن في المسجد... ويلحق بالمسجد في تحصيل هذه الفضيلة الاجتماع في مدرسة ورباط ونحوهما إن شاء الله تعالى.
الجزاء إنما رتَّبَه الله على الأعمال لا على الأنساب.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4801', false),
(20246, 2, 201, 246, 'hadith', 'عن أبي موسى الأشعري رضي الله عنه قال: كان النبي صلى الله عليه وسلم إذا أتاه طالب حاجة أقبل على جلسائه فقال: :اشفعوا تؤجروا ويقضي الله على لسان نبيه ما أحب" ((متفق عليه)). (16)', 'Whenever a needy person would come to the Prophet (ﷺ), he would turn to those who were present and say, "If you make intercession for him, you will be rewarded, because Allah decreed what He likes by the tongue of His Messenger"..', 'أبي موسى الأشعري رضي الله عنه', 'Abu Musa Al-Ash''ari (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 246', 'Riyad as-Salihin 246', 'ریاض الصالحین 246', null, 'هذا الحديث متضمن لأصل كبير وفائدة عظيمة، وهو أنه ينبغي للعبد أن يسعى في أمور الخير، سواء أثمرت مقاصدها ونتائجها أو حصل بعضها، أو لم يتم منها شيء. وذلك كالشفاعة لأصحاب الحاجات عند الملوك والكبراء، ومن تعلقت حاجاتهم بهم ، فإن كثيراً من الناس يمتنع من السعي فيها إذا لم يعلم قبول شفاعته. فيفوّت على نفسه خيراً كثيراً من الله، ومعروفاً عند أخيه المسلم. فلهذا أمر النبي صلّى الله عليه وسلم أصحابه أن يساعدوا أصحاب الحاجة بالشفاعة لهم عنده ليتعجلوا الأجر عند الله، لقوله: (اشفعوا تؤجروا) فإن الشفاعة الحسنة محبوبة لله، ومرضية له، قال تعالى: (من يَشْفَعْ شَفَاعَةً حَسَنَةً يَكُن لَّهُ نَصِيبٌ مِّنْهَا) ، ومع تعجله للأجر الحاضر، فإنه أيضاً يتعجل الإحسان وفعل المعروف مع أخيه، ويكون له بذلك عنده يد.
وأيضاً، فلعل شفاعته تكون سبباً لتحصيل مراده من المشفوع له أو لبعضه.
فالسعي في أمور الخير والمعروف التي يحتمل أن تحصل أو لا تحصل خير عاجل، وتعويد للنفوس على الإعانة على الخير، وتمهيد للقيام بالشفاعات التي يتحقق أو يُظن قبولها. 
قوله: "ويقضي الله على لسان نبيه ما شاء"، أي ما أراد مما سبق في علمه من وقوع الأمر وحصوله أو عدمه، فالمطلوب: الشفاعة. والثواب مرتب عليها، سواء حصل المشفوع به أو قام مانع من حصوله.', 'الترغيب في الشفاعة لما فيها من الأجر سواء أقضيت الحاجة أم لا.
لا شفاعة في حدود الله -تعالى-، إذا وصل أمرها إلى الحاكم.
رحمة النبي -صلّى الله عليه وسلم- في حصول الخير لأمته بكل طريق.
حصول الأجر للشافع، سواء قُضيت حاجة المشفوع أو لم تقض.
لا يقع إلا ما أراد الله -تعالى-.', 'اشفعوا : الشفاعة التوسط لقضاء حوائج الناس.
يقضي الله : القضاء الحكم والأداء.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3563', false),
(20247, 2, 201, 247, 'hadith', 'عن ابن عباس رضي الله عنهما في قصة بريرة وزوجها. قال: قال لها النبي صلى الله عليه وسلم: "لو راجعته؟" قالت: يا رسول الله تأمرني؟ قال : "إنما أشفع" قالت: لا حاجة لي فيه.', 'The Prophet (ﷺ) said to her, "It is better for you to go back to your husband." She asked: "O Messenger of Allah, do you order me to do so." He replied, "I only intercede" She then said: "I have no need for him"..', 'ابن عباس رضي الله عنهما', 'Ibn ''Abbas (May Allah bepleased with them), reported in connection with the case of Barirah (May Allah bepleased with her) and her husband:', 'صحيح', 'رياض الصالحين 247', 'Riyad as-Salihin 247', 'ریاض الصالحین 247', 'رواه البخاري', 'كان زوج بريرة رضي الله عنها عبدا يقال له مغيث رضي الله عنه، وكانت بريرة رضي الله عنها تخدم عائشة رضي الله عنها قبل شرائها، فلما أعتقتها، وجُعِل لها الخيار في البقاء مع مغيث أو الفراق فارقته بريرة رضي الله عنها، فكان مغيث رضي الله عنه بعد هذا التصدع الأسري يدور خلفها في سكك المدينة وطرقها يبكي ودموعه تسيل على لحيته؛ وهذا من شدَّة محبته لبريرة رضي الله عنها، علَّها تراجع قرارها وترجع إليه.
فقال النبي صلى الله عليه وسلم لبريرة رضي الله عنها: لو راجعته لكان لك ثواب. 
فقالت بريرة رضي الله عنها: يا رسول الله أتأمرني بمراجعته وجوبًا.
فقال صلى الله عليه وسلم: إنما أتوسط له.
 فقالت رضي الله عنها: لا غرض ولا رغبة لي في مراجعته.', 'قال النووي: أجمعت الأمة على أن الأمة إذا اعتقت كلها تحت زوجها وهو عبد كان لها الخيار في فسخ النكاح.
الإسلام يراعي الحقوق الشخصية والحرية التي يعتبر فيها الفرد عن كامل إرادته من غير إكراه.
الشفاعة ليست أمرا وإنما هي واسطة خير وتوسل ؛ لقضاء حاجة المسلم.
جواز رد الشفيع وليس ذلك قدح في الراد أو الشفيع.
استحباب الشفاعة فيما أجازه الشرع.
بذل الإحسان إلى الآخرين.
ظاهره امتثال بريرة رضي الله عنها لأمر النبي -صلى الله عليه وسلم- لو أمرها بذلك؛ لأنها سألته: أتأمرني؟ ولو لم تأتمر بأمره لكن سؤالها عبثًا.
في الحديث شفاعة الإمام إلى الرعية وهي من مكارم الأخلاق السنية.
عدم مؤاخذة الإمام على من امتنع من قبول شفاعته.
المرء إذا خير بين مباحين، فاختار ما ينفعه لم يلم، ولو أضر ذلك برفيقه.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3741', false),
(20248, 2, 201, 248, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول صلى الله عليه وسلم: «كل سلامى من الناس عليه صدقة، كل يوم تطلع فيه الشمس: تعدل بين الاثنين صدقة، وتعين الرجل على دابته فتحمله عليها، أو ترفع له عليها متاعه صدقة. والكلمة الطيبة صدقة، وبكل خطوة تمشيها إلى الصلاة صدقة، وتميط الأذى عن الطريق صدقة» ((متفق عليه)). (17)', 'Messenger of Allah (ﷺ) said, "On every joint of man, there is charity, on everyday when the sun rises: doing justice between two men is charity, and assisting a man to ride an animal or to load his luggage on it is charity; and a good word is charity, every step which one takes towards (the mosque for) Salat is charity, and removing harmful things from the way is charity"..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 248', 'Riyad as-Salihin 248', 'ریاض الصالحین 248', null, 'بَيَّنَ النبيُّ صلى الله عليه وسلم أنَّ على كلِّ مسلم مُكلَّف كلّ يوم بعدد كل مفصل من مفاصل عظامه صدقة تطوع لله تعالى على سبيل الشكر له على العافية، وأن جعل عظامه مفاصل يتمكن بها من القبض والبسط، وأنّ تلك الصدقة تتأدّى بأعمال البر كلها ولا تتوقف على إعطاء مال، ومنها: عدلك وإصلاحك بيـن متخاصمين صدقةٌ، وفي إعانتك لعاجز في دابته فتحمله عليها أو ترفع له متاعه صدقةٌ، والكلمة الطيبة من ذكر ودعاء وسلام وغيرها صدقةٌ، وبكل خطوةٍ تمشيها إلى الصلاة صدقةٌ، وإزالة ما يُتَأذّى به عن الطريق صدقةٌ.', 'تركيب عظام الآدمي وسلامتها من أعظم نعم الله تعالى عليه، فيحتاج كل عظم منها إلى تصدق عنه بخصوصه ليتم شكر تلك النعمة.
الترغيب في تجديد الشكر كل يوم لدوام تلك النعم.
الترغيب في المداومة على النوافل والصدقات كل يوم.
فضل الإصلاح بين الناس.
الحث على معونة الرجل أخاه؛ لأن معونته إياه صدقة.
الحث على حضور الجماعات والمشي إليها، وعمارة المساجد بذلك.
وجوب احترام طرق المسلمين بتجنب ما يؤذيهم أو يضر بهم.', 'سُلامى: بضم السين المهملة وتخفيف اللام مع القصر، وهي المفاصل، وقد ثبت في صحيح مسلم أنها ثلاثمائة وستون:', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66527', false),
(20249, 2, 201, 249, 'hadith', 'عن أم كلثوم بنت عقبة بن أبي معيط رضي الله عنها قالت سمعت رسول الله صلى الله عليه وسلم يقول: "ليس الكذاب الذي يصلح بين الناس فينمي خيرًا، أو يقول خيرًا" ((متفق عليه)). و في رواية مسلم زيادة، قالت: "و لم اسمعه يرخصه في شيء مما يقوله الناس الا في ثلاث، تعني: الحرب، و الاصلاح بين الناس، و حديث الرجل امراته، و حديث المرأة زوجها".', 'Messenger of Allah (ﷺ) said, ''The person who (lies) in order to conciliate between people is not a liar, when he conveys good or says (something) good"..The narration in Muslim added: She said, "I never heard him (she meant the Prophet (ﷺ)) giving permission of lying in anything except in three (things): war, conciliating between people and the conversation of man with his wife and the conversation of a woman with her husband".', 'أم كلثوم بنت عقبة بن أبي معيط رضي الله عنها', 'Umm Kulthum bint ''Uqbah (May Allah be pleased with her)', null, 'رياض الصالحين 249', 'Riyad as-Salihin 249', 'ریاض الصالحین 249', null, null, null, null, 'sunnah.com', null, false, null, false),
(20250, 2, 201, 250, 'hadith', 'عن عائشة رضي الله عنها قالت: سمع رسول الله صلى الله عليه وسلم صوت خصوم بالباب عالية أصواتهما، وإذا أحدهما يستوضع الآخر ويسترفقه في شيء، وهو يقول: والله لا أفعل، فخرج عليهما رسول الله صلى الله عليه وسلم فقال: «أين المتألي على الله لا يفعل المعروف؟ » فقال: أنا يا رسول الله ، فله أي ذلك أحب.', 'Messenger of Allah (ﷺ) heard the voices of altercation of two disputants at the door; both the voices were quite loud. One was asking the other to make his debts little (so that he could pay them) and was pleading with him to show leniency to him, whereupon the (other one) said: "By Allah, I will not do that". Then there came Messenger of Allah (ﷺ) to them and said, "Where is he who swore by Allah that he would not do good?" He said: "O Messenger of Allah, it is me. Now he may do as he desires"..', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 250', 'Riyad as-Salihin 250', 'ریاض الصالحین 250', 'متفق عليه', 'معنى الحديث: أن النبي صلى الله عليه وسلم سمع صوت خصمين يتنازعان في أمور مالية، وقد ارتفعت أصواتهما حتى وصلت إلى مسامع النبي صلى الله عليه وسلم في بيته، فأصغى النبي صلى الله عليه وسلم إلى هذه الأصوات، وإذا به يسمع أحد الرجلين "يستوضع الآخر ويسترفقه في شيء" أي يطلب منه أن يضع عنه شيئًا أو أن يرفق به "وهو يقول: والله لا أفعل، فخرج عليهما رسول الله صلى الله عليه وسلم فقال أين المُتألي على الله أن لا يفعل المعروف؟" أي: أين الحالف بالله على عدم فعل المعروف فقال: أنا يا رسول الله، فله أي ذلك أحب" أي أنا الذي حلفت، ولخصمي ما أحَبَّ من الوَضْع من الدَّيْن أو الرفق به، وفي رواية لأحمد (24405) وابن حبان (5032): "إن شئتَ وضعتُ ما نقصوا، وإن شئت من رأس المال، فوضعَ ما نقصوا"، سعى النبي صلى الله عليه وسلم في الصلح بين المتخاصمين، إما بالوضع أو الرفق، وفي الباب قصة مشابهة لهذا الحديث رواها البخاري (2424) ومسلم (1558)، عن كعب بن مالك رضي الله عنه، أنه كان له على عبد الله بن أبي حَدْرَد الأسلمي دين، فلقيه، فلزمه فتكلما حتى ارتفعت أصواتهما، فمر بهما النبي صلى الله عليه وسلم فقال: "يا كعب" وأشار بيده، كأنه يقول: النصف، فأخذ نصف ما عليه وترك نصفا".
فينبغي للمسلم أن يحرص على فعل الخير ومن ذلك الإصلاح بين الناس، فإذا رأى شخصين أو جماعتين أو قبيلتين بينهما نزاع وشقاق وتباغض واقتتال سعى للإصلاح بينهم لإزالة كل ما يؤدي إلى الفرقة والتباغض، ويحل محله الإخاء وتسود المحبة، فإن في ذلك الخير الكثير والثواب الجزيل، بل ذلك أفضل من درجة الصائم القائم المتصدق، قال -عليه الصلاة والسلام-: "ألا أخبركم بأفضل من درجة الصيام والصلاة والصدقة؟ قالوا: بلى، يا رسول الله قال: إصلاح ذات البين.." رواه أبو داود برقم (4919) وصححه الألباني في صحيح أبي داود، برقم (4919).', 'الحض على الرفق بالغريم والإحسان إليه بالوضع عنه.
الزجر على الحلف على ترك الخير، والسعي للإصلاح بين المتخاصمين.
لا يجوز الحلف على ترك فعل الخير.
السعي للإصلاح بين الخُصوم: قربة إلى الله -تعالى-.
استحباب الصفح عما يجري بين المتخاصمين من اللغط ورفع الصوت عند القاضي.
جواز طلب المدين من الدائن الإنظار أو الوضع ، لكن بشرط أن لا ينتهي إلى الإلحاح وإهانة النفس أو الإيذاء ونحو ذلك إلا من ضرورة.
وجوب إنظار المعسر والرفق به، قال -تعالى-: (وإن كان ذو عسرة فنظرة إلى ميسرة).
استحباب تدخل الإمام للإصلاح بين الخصمين.
الإنكار على من حلف لا يفعل خيرًا.
فيه الشفاعة إلى أصحاب الحقوق وقبول الشفاعة في الخير.
حرص النبي -صلى الله عليه وسلم- على الإصلاح بين ذات البين.
جواز المطالبة بالدين في المسجد.', 'له أي ذلك أحب : أي ليختر الرفق به ، أو وضع شيء من الدين عنه.
المتألي : الذين يحكمون على الله، ويقسمون.
يستوضع ويسترفق : يطلب أن ينقص عند السداد من دينه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3728', false),
(20251, 2, 201, 251, 'hadith', 'عن أبي العباس سهل بن سعد الساعدي رضي الله عنه ، أن رسول الله صلى الله عليه وسلم بلغه أن بني عمرو بن عوف كان بينهم شر، فخرج رسول الله صلى الله عليه وسلم يصلح بينهم في أناس معه ، فحبس رسول الله صلى الله عليه وسلم وحانت الصلاة، فهل لك أن تؤم الناس؟ قال: نعم إن شئت، فأقام بلال الصلاة، وتقدم أبو بكر فكبر وكبر الناس،وجاء رسول الله صلى الله عليه وسلم يمشي في الصفوف حتى قام في الصف، فأخذ الناس في التصفيق، وكان أبو بكر رضي الله عنه لا يلتفت في صلاته، فلما أكثر الناس التصفيق التفت، فإذا رسول الله صلى الله عليه وسلم، فأشار إليه رسول الله صلى الله عليه وسلم، فرفع أبو بكر رضي الله عنه يده فحمد الله، ورجع القهقرى وراءه حتى قام في الصف، فتقدم رسول الله صلى الله عليه وسلم، فصلى للناس، فلما فرغ أقبل على الناس فقال: «أيها الناس ما لكم حين نابكم شيء في الصلاة أخذتم في التصفيق ؟ إنما التصفيق للنساء. من نابه شيء في صلاته فليقل سبحان الله، فإنه لا يسمعه أحد حين يقول سبحان الله إلا التفت، : يا أبا بكر: ما منعك أن تصلي الناس حين أشرت إليك؟» فقال أبو بكر: ما كان ينبغي لابن أبي قحافة أن يصلي بالناس بين يدي رسول الله صلى الله عليه وسلم. ((متفق عليه)). (20).', 'There was some quarrel among the members of Banu ''Amr bin ''Auf. Messenger of Allah (ﷺ) went with some of his Companions to bring about peace between them and he was detained. The time for Salat approached and Bilal (May Allah be pleased with them) went to Abu Bakr (May Allah be pleased with him) and said to him: "Messenger of Allah (ﷺ) has got late and it is the time for Salat. Will you lead Salat?" He said: "Yes, if you desire". Bilal (May Allah be pleased with him) proclaimed the Adhan and then pronounced Iqamah. Abu Bakr (May Allah be pleased with him) stepped forward and commenced As- Salat. (He recited Takbir and the people followed him). In the meantime, Messenger of Allah (ﷺ) arrived and, passing through the rows, took his stand in the first row. The people started clapping. It was the habit of Abu Bakr (May Allah be pleased with him) that whenever he started praying, he would never look round. He paid no heed (to the clapping). When the clapping increased, he turned round and saw Messenger of Allah (ﷺ). He (the Prophet (ﷺ)) beckoned him to continue performing Salat. But Abu Bakr (May Allah be pleased with him) raised his hands and praised Allah. Then he retreated, taking his steps backwards. When Messenger of Allah (ﷺ) saw that, he went ahead and led Salat. When he finished Salat, he faced the congregation and said, "Why do you clap when something happens during the Salat. Clapping is only for women. If something happens in the course of Salat you should say, Subhan Allah. It is bound to attract attention. And you, Abu Bakr, what prevented you from carrying on with Salat, after I beckoned to do so?" He said, "It was not becoming for the son of Abu Quhafah to lead Salat in the presence of Messenger of Allah (ﷺ)"..', 'أبي العباس سهل بن سعد الساعدي رضي الله عنه', 'Sahl bin Sa''d As-Sa''idi (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 251', 'Riyad as-Salihin 251', 'ریاض الصالحین 251', null, 'بلغ رسول الله صلى الله عليه وسلم أن بني عمرو بن عوف كان بينهم خلاف، حتى وصل إلى الاقتتال، فخرج رسول الله صلى الله عليه وسلم ومعه بعض أصحابه، فتأخر عندهم ودخل وقت الصلاة: وهي صلاة العصر، كما صرح به البخاري في روايته ولفظه "فلما حضرت صلاة العصر أذن وأقام وأمر أبا بكر فتقدم" ثم جاء بلال إلى أبي بكر رضي الله عنه فقال: يا أبا بكر إن رسول الله صلى الله عليه وسلم قد حُبِسَ وحانت الصلاة فهل لك أن تؤم الناس؟ قال: "نعم إن شئت"، فأقام بلال وتقدم أبو بكر فكبر وكبر الناس، ثم جاء رسول الله صلى الله عليه وسلم يمشي في الصفوف، زاد البخاري في رواية: "يشقها شقاً" حتى قام في الصف الأول، كما في رواية مسلم: "فخرق الصفوف حتى قام عند الصفّ المقدم"، ولما علم الناس بوجود النبي صلى الله عليه وسلم معهم أخذوا في التصفيق؛ لمحبتهم الصلاة خلف رسول الله صلى الله عليه وسلم فأبو بكر رضي عنه سمع تصفيقهم لكن لم يدر ما السبب، وكان رضي الله عنه لا يلتفت لعلمه بالنهي عن الالتفات في الصلاة وأنه خلسة من الشيطان يختلسها من صلاة العبد كما جاء ذلك عند الترمذي وغيره، لكن لما أكثر الناس في التصفيق التفت رضي الله عنه فرأى رسول الله صلى الله عليه وسلم قد حضر إلى الصلاة فأشار إليه -عليه الصلاة والسلام- بالبقاء على ما هو عليه من إمامة الناس كما في رواية للبخاري: "فأشار إليه أن امكث مكانك" فرفع أبو بكر يده وحمد الله تعالى، على ما رآه من تعامل النبي صلى الله عليه وسلم معه، ثم رجع يمشي خطوات إلى الخلف حتى قام في صف المأمومين فتقدم رسول الله صلى الله عليه وسلم فصلى بالناس إمامًا، فلما فرغ -عليه الصلاة والسلام- من صلاته أقبل على الناس بوجهه، وقال: "يا أيها الناس، ما لكم حين نَابكم شيء في الصلاة أخذتم في التصفيق؟ إنما التصفيق للنساء" ثم بين لهم ما يسن لهم فعله فيما إذا نابهم شيء في الصلاة، فقال: (من نابه شيء في صلاته فليَقُل: سبحان الله، فإنه لا يسمعه أحد حين يقول: سبحان الله، إلا التَفت).
ثم قال: (يا أبا بكر: ما منعك أن تصلي بالناس حين أشرت إليك؟)، فقال أبو بكر: ما كان ينبغي لابن أبي قحافة أن يصلي بالناس بين يدي رسول الله صلى الله عليه وسلم ، وهذا من حبه وتعظيمه وإجلاله رضي الله عنه لرسول الله صلى الله عليه وسلم .', 'المسارعة إلى الإصلاح بين الناس لحسم مادة القطيعة بينهم، وتوجه الإمام بنفسه إلى بعض رعيته لذلك.
وجوب قيام الإمام على مصالح الرعية، وتحسس أوضاعهم والإشراف عليها بنفسه.
جواز الصلاة الواحدة بإمامين أحدهما بعد الآخر.
جواز التسبيح في الصلاة لما ينوب المصلي أو غيره.
جواز الالتفات في الصلاة للحاجة.
جواز الحركات إذا لم تكثر، ومخاطبة المصلي بالإشارة أولى من مخاطبته بالعبارة.
فضل أبي بكر الصديق -رضي الله عنه-، وأن المسلمين كانوا يعرفون له فضله في حياة النبي -صلى الله عليه وسلم-.
تواضعه -صلى الله عليه وسلم-.
جواز إمامة المفضول للفاضل، ولهذا قال الرسول -صلى الله عليه وسلم- لأبي بكر -رضي الله عنه-: (ما منعك أن تصلي بالناس حين أشرت إليك؟).
جواز تأخير الصلاة عن أول وقتها.
جواز تحول الإمام مأمومًا.
السنة فيما إذا ناب الإمام شيء في صلاته، أن يسبح الرجال وتصفق النساء.
أن إقامة الصلاة من اختصاص المؤذن حال غياب الإمام.
المشي بين الصفوف لا يقطع الصلاة.
حرص الصحابة -رضي الله عنهم- على الصلاة خلف رسول الله -صلى الله عليه وسلم-.
أن الالتفات لا يبطل الصلاة، إذا كان لحاجة.
تعظيم وتوقير أبي بكر -رضي الله عنه- للنبي -صلى الله عليه وسلم-.
جواز رفع اليدين عند الحمد والثناء على الله -تعالى-.', 'شَرٌّ : قتال.
حَانت الصلاة : دخل حينها وهو وقتها، وهي صلاة العصر، كما في صحيح البخاري.
القَهْقَرَى : يمشي إلى خلفه.
نَابَكُم : أصابكم.
ابن أبي قحافة : أبو قحافة اسمه عثمان وهو والد أبي بكر.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6973', false),
(20252, 2, 201, 252, 'hadith', 'عن حارثة بن وهب رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «ألا أخبركم بأهل الجنة؟ كل ضعيف متضعف ، لو أقسم على الله لأبره. ألا أخبركم بأهل النار؟ كل عتل جواظ مستكبر» ((متفق عليه)) . (21)', 'I heard Messenger of Allah (ﷺ) saying, "Shall I not inform you about the people of Jannah? It is every person who is, modest and humble (before Allah), a person who is accounted weak and is looked down upon but if he adjures Allah, Allah will certainly give him what he desires. Now shall I not inform you about the inmates of Hell? It is every violent, impertinent and proud man"..', 'حارثة بن وهب رضي الله عنه', 'Harithah bin Wahb (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 252', 'Riyad as-Salihin 252', 'ریاض الصالحین 252', null, 'أَخْبَرَ النبيُّ صلى الله عليه وسلم ببعض صفات أهل الجنة وأهل النار. 

فأغلب أهل الجنة هم: "كل ضعيف متضعِّف"، أي: متواضع خاضع لله تعالى، مُذِلّ نفسه له، حتى إن بعض الناس يَستَضعفونه ويَحتَقِرونه، وهذا المُتذَلِّل لله تعالى لو أقسم بالله يَمينًا طَمَعًا في كَرَم الله تعالى، لَأَبَرَّه الله، وحَقَّقَ له ما أَقْسَمَ عليه وأجاب طلبَه ودعاءه. 

وأغلب أهل النار هم: كل «عُتُل» وهو الفَظُّ الغَليظ شديد الخصومة، أو الفاحش الذي لا يَنْقَاد لخير، «جواظ» وهو المتكبر، الأَكُوْل، صاحب الجسد الضخم، المُختال في مِشيته، سيء الخلق، «مستكبر» برفضه للحق، وباحتقاره لغيره.', 'الحث على الاتصاف بصفات أهل الجنة، والتحذير من صفات أهل النار.
التواضع يكون لله عز وجل، ولأمره ونهيه والانقياد لهما، ويكون للخلق بعدم التكبُّر عليهم.
قال ابن حجر: المراد أن أغلب أهل الجنة هؤلاء، كما أن معظم أهل النار القسم الآخر، وليس المراد الاستيعاب في الطرفين.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3573', false),
(20253, 2, 201, 253, 'hadith', 'عن أبي العباس سهل بن سعد الساعدي رضي الله عنه قال: مر رجل على النبي صلى الله عليه وسلم، فقال لرجل عنده جالس: "ما رأيك في هذا؟" فقال: رجل من أشراف الناس، هذا والله حري إن خطب أن ينكح، وإن شفع أن يشفع . فسكت رسول الله صلى الله عليه وسلم، ثم مر رجل آخر، فقال له رسول الله صلى الله عليه وسلم: " ما رأيك في هذا؟" فقال: يا رسول الله هذا رجل من فقراء المسلمين هذا حري إن خطب أن لا ينكح، وإن شفع أن لا يشفع، وإن قال أن لا يسمع لقوله. فقال رسول الله صلى الله عليه وسلم: "هذا خير من ملء الأرض مثل هذا" ((متفق عليه)) . (22)', 'A man passed by the Prophet (ﷺ), so he asked a man who was sitting near him, "What is your opinion about this man?" That man replied: "He is one of the noblest men. By Allah he is certainly a proper person for (a girl) being given in marriage if he seeks to marry, and his recommendation is fit to be accepted if he recommends". Messenger of Allah (ﷺ) remained silent. Then another man passed. Messenger of Allah (ﷺ) enquired, "What is your opinion about this man?" He replied: "O Messenger of Allah, he is one of the poor Muslims. He is not a proper person (for a girl) to be given in marriage to, and his recommendation would not be accepted if he makes one; if he speaks, he is not to be listened to." Messenger of Allah (ﷺ) said, "He is better than the former by earthfuls"..', 'أبي العباس سهل بن سعد الساعدي رضي الله عنه', 'Sahl bin Sa''d As-Sa''idi (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 253', 'Riyad as-Salihin 253', 'ریاض الصالحین 253', null, 'معنى الحديث : مرَّ بالنبي صلى الله عليه وسلم رجلان، أحدهما: من أشراف القوم، وممن له كلمة فيهم، وممن يجاب إذا خطب، ويسمع إذا قال، والثاني بالعكس، رجل من ضعفاء المسلمين ليس له قيمة، إن خطب فلا يجاب، وإن شفع فلا يشفع، وإن قال فلا يسمع.
فقال النبي صلى الله عليه وسلم : (هذا خير من مِلء الأرض مثل هذا) أي: خير عند الله عز وجل من مِلء الأرض من مثل هذا الرجل الذي له شرف وجاه في قومه؛ لأن الله سبحانه وتعالى لا ينظر إلى الشرف، والجاه، والنسب، والمال، والصورة، واللباس، والمركوب، والمسكون، وإنما ينظر إلى القلب والعمل، وفي الحديث: (إن الله لا ينظر إلى صوركم، ولا إلى أموالكم، ولكن إنما ينظر إلى قلوبكم وإلى أعمالكم)، رواه مسلم.
فإذا صلح القلب فيما بينه وبين الله عز وجل ، وأناب إلى الله، وصار ذاكراً لله تعالى خائفاً منه، مخبتاً إليه، عاملاً بما يرضي الله عز وجل ، فهذا هو الكريم عند الله، وهذا هو الوجيه عنده، وهذا هو الذي لو أقسم على الله لأبره.', 'الحث على عدم الاستهانة بالفقراء والمستورين، فرب أشعث أغبر خير من مِلء الأرض من الأثرياء وأصحاب المظاهر.
التفاضل بين الناس بالتقوى، قال -تعالى-: (إن أكرمكم عند الله أتقاكم).
الترغيب في إنكاح الصالحين والصالحات، ولو كانوا فقراء؛ لأنهم الأكفاء في الدين.
إن السيادة لمجرد حيازة الدنيا لا أثر له في المجتمع الإسلامي، ومن فاته حظه من الدنيا أمكنه الاستعاضة عنه بالأعمال الصالحة والتقوى.
جواز استفتاح العالم جلسته بسؤال تلاميذه.
الله لا ينظر إلى صور الناس وأموالهم وأحسابهم وأنسابهم.
الترغيب في إنكاح الصالحين والصالحات؛ لأنهم أكفاء في الدين والخلق.
لا قيمة للعرف السائد الذي يخالف الشرع.
التكلم على من لم يكن حاضراً ليعلم الناس أمره، أو ليحذروا شره، لا يعد من الغيبة المحرمة.
فيه أن الرجل قد يكون ذا منزلة عالية في الدنيا، ولكنه ليس له قدر عند الله، وقد يكون في الدنيا ذا مرتبة منحطة وليس له قيمة عند الناس وهو عند الله خير من كثير ممن سواه.', 'مر رجل : قيل لعله الأقرع بن حابس أو عيينة بن حصن، والرجل الآخر قيل: هو جميل بن سراقة الغفاري.
حري : حقيق وجدير.
شفع : الشفاعة: التوسط لالتماس العفو أو التخفيف من العقوبة من غير دليل.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3880', false),
(20254, 2, 201, 254, 'hadith', 'عن أبي سعيد الخدري رضي الله عنه عن النبي صلى الله عليه وسلم قال: « احتجت الجنة والنار فقالت النار: في الجبارون والمتكبرون، وقالت الجنة: في ضعفاء الناس ومساكينهم، فقضى الله بينهما: إنك الجنة رحمتي أرحم بك من أشاء، وإنك النار أعذب بك من أشاء، ولكليكما علي ملؤها».', 'The Prophet (ﷺ) said: There was a dispute between the Hell and Jannah. The Hell said: "The haughty and proud are my inmates." Jannah said: "The modest and the humble are my residents". Thereupon, Allah the Exalted and Glorious (addressing Jannah) said: "You are My Mercy, through you I shall show mercy to those whom I wish". (And addressing the Hell), He said: "You are (the means) of My punishment by which I shall punish such of My slaves as I wish and each one of you would have its fill"..', 'أبي سعيد الخدري رضي الله عنه', 'Abu Sa''id Al-Khudri (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 254', 'Riyad as-Salihin 254', 'ریاض الصالحین 254', 'رواه مسلم', 'معنى هذا الحديث: أن الجنة والنار تحاجتا فيما بينهما، كل واحدة تدلي بحجتها، وهذا من الأمور الغيبية التي يجب علينا أن نؤمن بها حتى وإن استبعدتها العقول 
فالجنة احتجت على النار، والنار احتجت على الجنة، النار احتجت بأن فيها الجبارين والمتكبرين، الجبارون أصحاب الغلظة والقسوة، والمتكبرون أصحاب الترفع والعلو، والذين يغمطون الناس ويردون الحق، كما قال النبي صلى الله عليه وسلم في الكبر: (إنه بطر الحق وغمط الناس).
فأهل الجبروت وأهل الكبرياء هم أهل النار والعياذ بالله، وربما يكون صاحب النار لين الجانب للناس، حسن الأخلاق، لكنه جبار بالنسبة للحق، مستكبر عن الحق، فلا ينفعه لينه وعطفه على الناس، بل هو موصوف بالجبروت والكبرياء ولو كان لين الجانب للناس؛ لأنه تجبر واستكبر عن الحق.
أما الجنة فقالت: إن فيها ضعفاء الناس وفقراء الناس. فهم في الغالب الذين يلينون للحق وينقادون له، وأما أهل الكبرياء والجبروت؛ ففي الغالب أنهم لا ينقادون.
فقضى الله عز وجل بينهما فقال للجنَّة : ( إنك الجنة رحمتي أرحم بك من أشاء ) وقال للنار: ( إنك النار عذابي أعذب بك من أشاء ) 
ثم قال عز وجل: ( ولكليكما عليَّ ملؤها ) تكفل عز وجل وأوجب على نفسه أن يملأ الجنة ويملأ النار، وفضل الله سبحانه وتعالى ورحمته أوسع من غضبه، فإنه إذا كان يوم القيامة ألقى من يلقى في النار، وهي تقول : هل من مزيد، يعني أعطوني. أعطوني. زيدوا. فيضع الله عليها رجله، وفي لفظ عليها : قدمه، فينزوي بعضها على بعض، ينضم بعضها إلى بعض من أثر وضع الرب عز وجل عليها قدمه، وتقول: قط قط، يعني: كفاية كفاية، وهذا ملؤها.
أما الجنة فإن الجنة واسعة، عرضها السَّمَوَاتِ والأرض يدخلها أهلها ويبقى فيها فضل زائد على أهلها، فينشئ الله تعالى لها أقواماً فيدخلهم الجنة بفضله ورحمته؛ لأن الله تكفل لها بملئها.', 'بشارة المؤمنين المستضعفين بالجنة، ووعيد المتكبرين والجبارين بالنار.
أن الله تعالى شاء أن يترك الناس أحراراً يختار كل واحد منهم العمل الذي يريده بعد أن يبين لهم طريق الحق من الباطل، وقد علم سبحانه أن فريقاً سيختار طريق الشر ويكون مصيره النار فيملؤها ، وأن فريقاً سيختار بإرادته طريق الخير فيكون مصيره الجنة فيملؤها .
هذا الحديث على ظاهره، فقد جعل الله في الجنة والنار تمييزاً تدركان به؛ فتحاجتا وكان لهما قولاً.
التواضع لله وخفض الجناح للمؤمنين سبب في رحمة الله ودخول الجنة.
الجنة دار رحمة الله يرحم بها من يشاء من أوليائه، والنار دار عذابه يعذب بها من يشاء من أعدائه.
جواز المناظرة، وأنها مشروعة لإظهار الحق وإزهاق الباطل.
أن الفقراء والضعفاء هم أهل الجنة؛ لأنهم في الغالب هم الذين ينقادون للحق، وأن الجبارين المتكبرين هم أهل النار والعياذ بالله؛ لأنهم مستكبرون على الحق .', 'احتجت : تخاصمت وأقامت كل واحدة منهما الحجة على الأخرى ، والمراد من الحوار حكاية ما اختص به كل منهما.
الجبارون : الذين يتجبرون على الناس ويقهرونهم على مرادهم.
ضعفاء الناس : المتواضعون،أو المستضعفون.
مساكينهم : المحتاجون.
قضى بينهم : أخبر عما أراده لها مما سبقت به إرادته.
لكليكما علي ملؤها : لكل من الجنة والنار ما يملؤها.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3261', false),
(20255, 2, 201, 255, 'hadith', 'عن أبي هريرة رضي الله عنه عن رسول الله صلى الله عليه وسلم قال: « إنه ليأتي الرجل السمين العظيم يوم القيامة لا يزن عند الله جناح بعوضة».', 'Messenger of Allah (ﷺ) said, "On the Day of Resurrection, there will be brought forth a bulky person (person of noteworthy status) whose value to Allah will be less than that of the wing of a mosquito"..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 255', 'Riyad as-Salihin 255', 'ریاض الصالحین 255', 'متفق عليه', 'إن الرجل العظيم صاحب البنية الضخمة المتعاظم على خلق الله في الدنيا المتجبر المتغطرس بأفعاله وأقواله، فإنه يوم القيامة لا يزن عند الله جناح بعوضة، ولا تكون له قيمة ولا منزلة.', 'أن قيمة الإنسان بعمله لا بشكله وجسمه يوم القيامة.
العبرة بالمقاييس الشرعية لا بالتصورات البشرية .
أنَّ ذا القَدْر والجَاه في الدنيا إذا لم يكن ذا تقوى، فليس له قَدْر عند الله -تعالى-.', 'لا يزن عند الله : لا قيمة له عند الله ولا منزلة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3776', false),
(20256, 2, 201, 256, 'hadith', 'وعنه أن امرأة سوداء كانت تقم المسجد، أو شابا، ففقدها، رسول الله صلى الله عليه وسلم، فسأل عنها أو عنه، فقالوا: مات. قال: " أفلا كنتم آذنتموني" فكأنهم صغروا أمرها، أو أمره، فقال: " دلوني على قبره" فدلوه فصلى عليه، ثم قال: " إن هذه القبور مملوءة ظلمة على أهلها، وإن الله تعالى ينورها لهم بصلاتي عليهم" ((متفق عليه)). (23)', 'A black woman (or probably a young man) used to clean the mosque. Messenger of Allah (ﷺ) missed her (or him) and asked about her (or him). He was told that she (or he) had died. He (ﷺ) said, "Why did you not inform me?" (It seemed as if) they (Companions) considered the matter insignificant. Then he (ﷺ) said, "Show me her (or his) grave." When it was shown to him, he offered (Janazah-funeral) prayer over it and said, "These graves cover those in them with darkness, and Allah illumines them for the inmates as a result of my supplication for them"..', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 256', 'Riyad as-Salihin 256', 'ریاض الصالحین 256', null, 'روى أبو هريرة رضي الله عنه أن امرأة سوداء كانت تكنس وتجمع قمامة المسجد، وتخرجه منه؛ اعتناءً بنظافة المسجد وتعظيمًا له، أو كان شابًا شك الراوي، ففقدها رسول الله صلى الله عليه وسلم وطلبها عند غيبتها، فسأل عن حال تلك المرأة السوداء فقالوا: مات، فقال عليه الصلاة والسلام: أفلا كنتم أعلمتنموني بموتها حتى أصلي عليها، فكأن الصحابة صغَّروا وقلَّلوا شأنها وأمرها، فقال: دلوني وأخبروني على قبره أين هو؟ فدلوه، فأتى القبر وصلى عليها ثم قال عليه الصلاة والسلام: إن هذه القبور مملوءة ظلمة على أهلها فهي مظلمة على الموتى، وإن الله عز وجل ينورها ويضيؤها لهم بسبب صلاتي عليهم.', 'فضل تنظيف المسجد.

السؤال عن الخادم والصديق إذا غاب وتفقده.

المكافأة بالدعاء، والترحم على من وقف نفسه على نفع المسلمين ومصالحهم.

الترغيب في شهود جنائز أهل الخير.

استحباب الصلاة على الميت الحاضر عند قبره لمن لم يصل عليه.

مشروعية الإعلام بموت الإنسان حتى يجتمع المسلمون فيصلوا عليه، لقوله صلى الله عليه وسلم: "أفلا كنتم آذنتموني".

الرد على قول من كره الإخبار بالجنازة، وألا يُشعَر بجنازة الميت جارٌ ولا غيره.

مشروعية الصف في الصلاة على الجنازة.

بيان أن صلاته صلى الله عليه وسلم على أمته رحمة لهم، ونور يزيل ظلمة القبر عنهم.

ما كان عليه النبي صلى الله عليه وسلم من كمال الأخلاق، وكمال الرأفة بأمته، حيث كان يعتني بالضعفاء والمساكين أشد عناية، فيسأل عن أحوالهم ويعود مرضاهم ويصلي على موتاهم ويشيع جنائزهم، فكان صلى الله عليه وسلم في الذروة العليا من مكارم الأخلاق، كما وصفه الله سبحانه وتعالى بذلك، حيث قال: {وإنك لعلى خلق عظيم (4)} [القلم: 4].', 'تقُم: تكنس.

آذنتموني: أعلمتومني.

صغروا: قللوا.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65413', false),
(20257, 2, 201, 257, 'hadith', 'وعنه قال: قال رسول الله صلى الله عليه وسلم: «رب أشعث أغبر مدفوع بالأبواب لو أقسم على الله لأبره ».', 'Messenger of Allah (ﷺ) said, "Many a person with shaggy and dusty hair, dusty and driven away from doors (because of their poverty and shabby clothes) were to swear by Allah (that something would happen), Allah will certainly make it happen"..', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 257', 'Riyad as-Salihin 257', 'ریاض الصالحین 257', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(20258, 2, 201, 258, 'hadith', 'عن أسامة رضي الله عنه عن النبي صلى الله عليه وسلم قال: « قمت على باب الجنة، فإذا عامة من دخلها المساكين، وأصحاب الجد محبوسون، غير أن أصحاب النار قد أمر بهم إلى النار. وقمت على باب النار فإذا عامة من دخلها النساء» ((متفق عليه)). (24)', 'The Prophet (ﷺ) said, "I stood at the gate of Jannah, and (I saw) that the majority of those who entered it are the poor, and the wealthy were kept confined. The inmates of the Fire had been ordered to (enter) the Fire (Hell), and I stood at the gate of Hell and saw that the majority of its inmates are women"..', 'أسامة رضي الله عنه', 'Usamah bin Zaid (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 258', 'Riyad as-Salihin 258', 'ریاض الصالحین 258', null, 'الفقراء والمساكين يدخلون الجنة قبل الأغنياء؛ وذلك لأنهم فقراء لا مال لهم يحاسبون عليه، وإكرامًا من الله تعالى لهم، وتعويضًا لهم على ما فاتهم من نعيم الدنيا وزينتها، أما أصحاب الحظ الفاني من أرباب الأموال والمناصب فهم محبوسون في عرصات القيامة لطول حسابهم في المتاعب بسبب كثرة أموالهم، وتوسيع جاههم، وتلذذهم بهما في الدنيا، وتمتعهم على وفق شهوات النفس والهوى، فإن حلال الدنيا حساب وحرامها عقاب، والفقراء من هذا براء، وأكثر من يدخل النار النساء؛ لأنهن يكثرن الشكاية وينكرن جميل الأزواج.', 'إخبار النبي صلى الله عليه وسلم بالمغيبات بأحوال أهل الجنة والنار.
أول من يدخل الجنة المساكين والفقراء، إكرامًا لهم على ما فاتهم من نعيم الدنيا.
لا ينفع مال ولا بنون يوم القيامة إلا من أتى الله بقلب سليم.
النساء اللاتي يعصين ربهن وينكرن الجميل ويكفرن العشير يدخلن النار.
المال مسؤولية كبيرة عند الله تعالى، فينبغي على مالكه أن يضعه حيث أمر الله ليكون حسابه يوم القيامة يسيرا.
فضل الفقراء الصابرين على الضراء.
أن الذين يؤدون حقوق المال، ويسلمون من فتنته هم الأقلون، وأن الكفار يدخلون النار ولا يحبسون عنها.', 'الجد : الغنى.
محبوسون : أي لم يؤذن لهم بعد في دخول الجنة إما لوقوفهم للحساب، وإما ليسبقهم إليها صالحو الفقراء.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3745', false),
(20259, 2, 201, 259, 'hadith', 'عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال: " لم يتكلم في المهد إلا ثلاثة: عيسى ابن مريم، وصاحب جريج، وكان جريج رجلا عابدًا، فاتخذ صومعة فكان فيها، فأتته أمه وهو يصلي فقالت: يا جريج، فأتته أمه وهو يصلي فقالت: يا جريج، فقال: يا رب أمي وصلاتي فأقبل على صلاته فانصرفت. فلما كان من الغد أتته وهو يصلي، فقالت: يا جريج، فقال: أي رب أمي وصلاتي، فأقبل على صلاته، فقالت: اللهم لاتمته حتى ينظر إلى وجوه المومسات. فتذاكر بنو إسرائيل جريجًا وعبادته، وكانت امرأة بغي يتمثل بحسنها، فقالت: إن شئتم لأفتننه، فتعرضت له، فلم يلتفت إليها، فأتت راعيًا كان يأوي إلى صومعته، فأمكنته من نفسها فوقع عليها. فحملت، وجعلوا يضربونه، فقال: ما شأنكم؟ قالوا: زنيت بهذه البغي فولدت منك. قال: أين الصبي؟ فجاءوا به فقال: دعوني حتى أصلي، فصلى، فلما انصرف أتى الصبي فطعن في بطنه وقال: ياغلام من أبوك؟ قال: فلان الراعي، فأقبلوا على جريج يقبلونه ويتمسحون به وقالوا: نبني لك صومعتك من ذهب، قال: لا، أعيدوها من طين كما كانت، ففعلوا. وبينا صبي يرضع من أمه، فمر رجل راكب على دابة فارهة وشارة حسنة، فقالت: " اللهم اجعل ابني مثل هذا، فترك الثدي وأقبل إليه فنظر إليه فقال: اللهم لا تجعلني مثله، ثم أقبل على ثديه فجعل يرتضع" فكأني أنظر إلى رسول الله صلى الله عليه وسلم وهو يحكي ارتضاعه بأصبعه السبابة في فيه، فجعل يمصها، قال: "ومروا بجارية وهم يضربونها، ويقولون: زنيت سرقت، وهي تقول: حسبي الله ونعم الوكيل. فقالت أمه: اللهم لا تجعل ابني مثلها، فترك الرضاع ونظر إليها فقال: اللهم اجعلني مثلها، فهناك تراجعا الحديث فقالت: مر رجل حسن الهيئة فقلت: اللهم اجعل ابني مثله فقلت: اللهم لا تجعلني مثله، ومروا بهذه الأمة وهم يضربونها ويقولون: زنيت سرقت، فقلت: اللهم لا تجعل ابني مثلها فقلت: اللهم اجعلني مثلها؟! قال: إن ذلك الرجل كان جبارًا فقلت: اللهم لا تجعلني مثله، وإن هذه يقولون لها زنيت، ولم تزن وسرقت، ولم تسرق، فقلت: اللهم اجعلني مثلها" ((متفق عليه)). (25)', 'The Prophet (ﷺ) said, "None spoke in the cradle but only three (persons), Isa (Jesus) son of Maryam (Mary), the second one was the companion of Juraij who was a pious person. Juraij took a secluded monastery for worship and confined himself in it. His mother came to him as he was busy in prayer and she called: ''Juraij.'' He said: ''My Rubb, my mother (is calling me while I am engaged in) my prayer.'' He continued with the prayer. She returned and she came on the next day and he was (still) busy in prayer. She called: ''Juraij.'' And he said: ''My Rubb, my mother (is calling me while I am engaged) in prayer, and he continued with the prayer,'' and she returned. Then on the next day she again came while he was busy in prayer and called: ''Juraij.'' And he said: ''My Rubb, my mother (is calling me while I am engaged) in my prayer.'' And he continued with the prayer. She said: ''My Rubb, don''t let him die until he has seen the faces of the prostitutes.'' The story of Juraij and that of his meditation and prayer spread amongst Banu Israel. There was a prostitute who had been a beauty personified. She said (to the people): ''If you like, I can lure him to evil.'' She presented herself to him but he paid no heed (to her). She came to a shepherd who lived near the temple and she offered herself to him. He (the shepherd) had sexual intercourse with her and so she became pregnant. When she gave birth to a baby she said: ''This is from Juraij.'' So they came and asked Juraij to get down and demolished the temple and began to beat him. He asked them what the matter was. They said: ''You have committed fornication with this prostitute and she has given birth to a baby from you.'' He said: ''Where is the baby?'' They brought him (the baby) and then he said: ''Just leave me so that I should perform prayer.'' He performed prayer and when he finished, he lifted the baby in his stomach and asked him: ''O boy, who is your father?'' The baby answered: ''He is such and such a shepherd.'' So, the people turned towards Juraij, kissed him and touched him (for seeking blessing) and said: ''We are prepared to construct your temple with gold.'' He said, ''No just, rebuild it with mud as it had been,'' and so they did". (The Prophet (ﷺ) continued:) "Then there was a baby who was sucking at his mother''s breast when a person dressed in fine garment came on a priceless riding animal''s back. His mother said: ''O Allah, make my child like this one.'' He (the babe) left sucking and looked at him, and said: ''O Allah, don''t make me like him.'' He then returned to the breast and resumed sucking." He (Abu Hurairah (May Allah be pleased with him) said: As though I can see Messenger of Allah (ﷺ) as he is illustrating the scene of his sucking milk with his forefinger in his mouth and sucking that. He (Abu Hurairah (May Allah be pleased with him)) further reported Messenger of Allah (ﷺ) as saying, "There happened to pass by them a slave girl who was being beaten and they were saying: ''You have committed fornication and theft.'' She was saying: ''Allah is enough for me and He is my Good Protector, and his mother said: ''O Allah, don''t make my child like her.'' He left sucking looked at her and said: ''O Allah! Make me like her.'' It was followed by a conversation between the mother and the child. She said: ''A good looking man happened to pass by and I said: O Allah, make my child like him, and you said: O Allah, don''t make me like him, and there passed a girl while they were beating her and saying: You committed fornication and theft, and I said: O Allah, don''t make my child like her, and you said: O Allah, make me like her.'' The child said: ''That man was a tyrant, and I said: O Allah don''t make me like him; and they were saying about the girl: You committed fornication, whereas in fact she had not committed that and they were saying: You have committed theft, whereas she had not committed theft, so I said: O Allah, make me like her"..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 259', 'Riyad as-Salihin 259', 'ریاض الصالحین 259', null, 'عن أبي هريرة رضي الله عنه عن نبينا صلى الله عليه وسلم أنه قال: (لم يتكلم في المهد إلا ثلاثة) والمراد في الأيام الأولى من طفولته، وهم:
أولا: عيسى بن مريم صلى الله عليه وسلم ، وكان آية من آيات الله عز وجل وقد تكلم وهو في المهد.
ثانيًا: صاحب جريج، وجريج رجل عابد، برأ الله جريجًا من هذه التهمة التي أرادوا إلصاقها به، وأظهر هذه الآية كرامة له، وهي أن ينطق الصبي ببراءته، وذلك أنه اتخذ مكان يخلو فيه للعبادة، فأتته أمه يومًا وهو يصلي، فقالت: يا جريج، فقال: يا رَبِّ أُمِّي وصلاتي. تردد هل يقطع الصلاة ليجيب أمه أم يكمل صلاته، فأقبل على صلاته فذهبت أمه. فلمَّا كان من الغَدِ أتَتْهُ وهو يصلي، فتكرر ما حصل بالأمس، فلمَّا كان من الغَدِ أتَتْهُ وهو يصلي، فتكرر منه ذلك فقالت أمه: اللَّهُمَّ لاَ تُمِتْهُ حتى يَنظر إلى وجوه المُومِسَاتِ أي الزانيات. فتذاكر بَنُو إسرائيل جُريجا وعبادته، وكانت امرأة زانية يُتَمَثَّلُ بحُسنها، فقالت: إن شِئتم لأغرينه حتى يدع صلاته ويقع في الزنى، فتَعرَّضت له، فلم يَلتَفت إليها، فأتت راعِيًا فَأَمْكَنَتْه من نَفسِها فزنى بها، فحملت، فلمَّا ولدت، قالت: هو من جُريج، فَأتَوْهُ وأنزلوه وهدَمُوا صَومَعتَه، وجَعَلوا يَضربونه، فقال: ما شَأنُكم؟ قالوا: زَنَيْتَ بهذه البَغِيِّ فولَدَت منك. قال: أين الصَّبي؟ فجاؤَوا به فقال: دَعوني حتى أُصلَّي، فصلَّى فلمَّا انْصرف أتى الصَّبي فَطَعن بأصبعه في بَطنه، وقال: يا غُلام مَنْ أبوك؟ قال: فلانٌ الراعي، فأقبلوا على جُريج يقبلونه ويَتمسَّحون به، وقالوا: نَبْنِي لك صَوْمَعَتَكَ من ذهب. قال: لا، أعِيدُوها من طين كما كانت، ففعلوا. 
ثالثًا: هذا الصبي الذي كان مع أمه يرضع، فمر رجل على فرس نفيسة وهيئته حسنة، وحكى النبي صلى الله عليه وسلم ارتضاع هذا الطفل من ثدي أمه بأن وضع إصبعه السبابة في فمه يمص، تحقيقا للأمر، فقالت: اللهم اجعل ابني مثله. فقال الطفل: اللهم لا تجعلني مثله. ثم أقبلوا بجارية؛ امرأة مملوكة يضربونها ويقولون لها: زنيت، سرقت. وهي تقول: حسبنا الله ونعم الوكيل. فقالت المرأة أم الصبي وهي ترضعه: اللهم لا تجعل ابني مثلها. فأطلق الثدي، ونظر إليها، وقال: اللهم اجعلني مثلها.
فتراجع الحديث مع أمه؛ طفل يتكلم معها، قالت: إني مررت أو مر بي هذا الرجل ذو الهيئة الحسنة فقلت: اللهم اجعل ابني مثله، فقلت أنت: اللهم لا تجعلني مثله، فقال: نعم؛ هذا رجل كان جبارا عنيدا فسألت الله ألا يجعلني مثله.
أما المرأة فإنهم يقولون: زنيت وسرقت، وهي تقول: حسبي الله ونعم الوكيل، فقلت: اللهم اجعلني مثلها. أي اجعلني طاهرا من الزنى والسرقة مفوضا أمري إلى الله، في قولها: حسبي الله ونعم الوكيل.', 'إيثار إجابة الأم على صلاة التطوع؛ لأن الاستمرار فيها نافلة وإجابه الأم وبرها واجب.
عظم بِرِّ الوالدين وإجابة دعائهما ولو كان الولد معذورا؛ لكن يختلف الحال في ذلك بحسب المقاصد.
مَكْرُ أهل الباطل بالصالحين قديم؛ فبنوا إسرائيل تآمروا على جريج وحرضوا البغي عليه، فلما ظنوا أنهم أصابوا منه مقتلاً زعموا أنهم يأدبونه للإصلاح، ولو كانوا مصلحين لأقاموا الحد على هذه المرأة البغي.
فيه دليل على صبر جريج، حيث إنه لم ينتقم لنفسه، ولم يكلفهم شططا فيبنون له صومعته من ذهب، وإنما رضي بما كان رضي به أولا من القناعة وأن تبنى من الطين.
أن الوضوء كان معروفا في شرع من قبلنا، فقد ثبت في هذا الحديث في صحيح البخاري: (فتوضأ وصلى).
الالتجاء إلى الله بالصلاة عند الكِرْب، وفي الحديث الآخر: (كان إذا حزبه أمر بادر إلى الصلاة).
صاحب الصِّدق مع الله لا تَضُرُّه الفِتن.
قوة يَقِين جُريج وصحة رجائه، لأنه استنطق المولود مع كون العادة أنه لا ينطق؛ ولولا صحة رجائه بنطقه ما استنْطَقه.
ثبوت الكرامة للصالحين من الرجال والنساء، وثبوت المعجزة للأنبياء.
يجعل الله -تعالى- لأوليائه مخارجًا عند ابتلائهم بالشدائد غالبًا، قال الله -تعالى-: (ومن يتق الله يجعل له مخرجًا) وإنما يتأخر ذلك عن بعضهم في بعض الأوقات تهذيبًا وزيادةً لهم في الثواب.', 'المهد : السرير يهيأ للصبي ويوطأ لينام فيه، والمراد في الأيام الأولى من الطفولة.
المُومِسَاتِ : الزَّواني.
صومعته : الصَوْمَعَة بيت العِبادة عند النصارى ومتَعَبَّد الناسك.
بَغِيٌّ : المرأة الفاجرة.
لأفتننه : الفتنة: الاختبار والابتلاء والإعجاب بالشيء.
اسْتَنْزَلُوهُ : أنْزَلُوه.
طَعَنَ في بَطْنِه : وخَزَه برأس أُصْبُعه في بطنه.
حَسْبِيَ الله : كافِيني الله.
دَابة فَارِهة : حَاذِقة نَفِيسَة.
الأَمَة : المرأة المملوكة، خلاف الحُرَّة.
الشَّارَةُ : الجَمَال الظاهر في الهيئة والمَلبس.
فِيه : فَمِه.
تَرَاجَعَا الحديث : حَدَّثت الصَّبي وحَدَّثها.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/7041', false),
(20260, 2, 201, 260, 'hadith', 'عن سعد بن أبي وقاص رضي الله عنه قال: كنا مع النبي صلى الله عليه وسلم ستة نفر، فقال المشركون للنبي صلى الله عليه وسلم: اطرد هؤلاء لايجترئون علينا، وكنت أنا وابن مسعود ورجلان لست أسميهما، فوقع في نفس رسول الله صلى الله عليه وسلم ما شاء الله أن يقع، فحدث نفسه، فأنزل الله تعالى: {ولا تطرد الذين يدعون ربهم بالغداة والعشي يريدون وجهه}.', 'Six of us were with the Prophet (ﷺ) when the infidels said to him: "Drive these ones away, lest they should begin to venture against us". The six were, myself, Ibn Mas''ud, a man of the Hudhail tribe, Bilal and two other men whose names I don''t know. Messenger of Allah (ﷺ) thought what Allah wished him to think, and Allah revealed: "And turn not away those who invoke their Rubb, morning and afternoon seeking His Face." (6:52).', 'سعد بن أبي وقاص رضي الله عنه', 'Sa''d bin Abu Waqqas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 260', 'Riyad as-Salihin 260', 'ریاض الصالحین 260', 'الأنعام: 52: رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(20261, 2, 201, 261, 'hadith', 'عن أبي هبيرة عائذ بن عمرو المزني وهو من أهل بيعة الرضوان رضي الله عنه، أن أبا سفيان أتى على سلمان وصهيب وبلال في نفر فقالوا: ما أخذت سيوف الله من عدو الله مأخذها، فقال أبو بكر رضي الله عنه: أتقولون هذا لشيخ قريش وسيدهم؟ فأتى النبي صلى الله عليه وسلم، فأخبره فقال: «يا أبا بكر لعلك أغضبتهم؟ لئن كنت أغضبتهم لقد أغضبت ربك» فأتاهم فقال: ياإخوتاه أغضبتكم؟ قالوا: لا، يغفر الله لك يا أخي.', 'Abu Sufyan passed by Salman, Suhaib and Bilal and some other Companions (May Allah be pleased with them). They said to him: "Did not the swords of Allah exact their due from the foes of Allah?" Abu Bakr (May Allah be pleased with him) said to them: "Do you speak like this to the chief of the Quraish and their master?" Then he went to the Prophet (ﷺ) and related this to him. He (ﷺ) said, "Abu Bakr, perhaps you have angered them. If so, you have angered your Rubb". Abu Bakr (May Allah be pleased with him) went back to them and said: "Brothers, did I offend you?" They replied: "No. May Allah forgive you, brother"..', 'أبي هبيرة عائذ بن عمرو المزني وهو من أهل بيعة الرضوان رضي الله عنه', '''Aidh bin ''Amr Al-Muzani (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 261', 'Riyad as-Salihin 261', 'ریاض الصالحین 261', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(20262, 2, 201, 262, 'hadith', 'عن سهل بن سعيد رضي الله عنه: قال رسول صلى الله عليه وسلم: « أنا وكافل اليتيم في الجنة هكذا» وأشار بالسبابة والوسطى، وفرج بينهما.', 'Messenger of Allah (ﷺ) said, "I will be like this in Jannah with the person who takes care of an orphan". Messenger of Allah (ﷺ) raised his forefinger and middle finger by way of illustration..', 'سهل بن سعيد رضي الله عنه', 'Sahl bin Sa''d (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 262', 'Riyad as-Salihin 262', 'ریاض الصالحین 262', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(20263, 2, 201, 263, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: « كافل اليتيم له أو لغيره أنا وهو كهاتين في الجنة» وأشار الراوي وهو مالك ابن أنس بالسبابة والوسطى.', 'Messenger of Allah (ﷺ) said, "He who takes care of an orphan, whether he is his relative or a stranger, will be in Jannah with me like these two". The narrator, Malik bin Anas raised his forefinger and middle finger for illustration..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 263', 'Riyad as-Salihin 263', 'ریاض الصالحین 263', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(20264, 2, 201, 264, 'hadith', 'وعنه قال: قال رسول الله صلى الله عليه وسلم: « ليس المسكين الذي ترده التمرة والتمرتان، ولا اللقمة واللقمتان إنما المسكين الذي يتعفف».', 'Messenger of Allah (ﷺ) said, "A Miskin (needy) is not the one who can be turned away with a date-fruit or two, or a morsel or two. The true Miskin is one who, despite his poverty, abstains from begging"..', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 264', 'Riyad as-Salihin 264', 'ریاض الصالحین 264', 'متفق عليه', 'يُوضح هذا الحديث حقيقة المسكنة، وأن المسكين الممدوح من المساكين الأحق بالصدقة والأحوج بها هو المتعفف، وإنما نفى صلى الله عليه وسلم المسكنة عن السائل الطوَّاف؛ لأنه تأتيه الكفاية، وقد تأتيه الزكاة فتزول خصاصته، وإنما تدوم الحاجة فيمن لا يسأل ولا يعطف عليه فيعطى.', 'ذم المسألة.
الحض على التعفف، قال تعالى مادحا أهل التعفف: "يحسبهم الجاهل أغنياء من التعفف".
المَسْكَنة صفة تُمدح إذا لازَمَتها العِفَّة عن السؤال، والصبر على الشِدَّة، والرِضى بما قسم الله.
مدح الحياء في كل الأحوال والأحيان، وأنه لا يأتي إلا بخير.
استحباب التحَرِّي لِوضع الصدقة فيمن صفته التعفُّف دون الإلحاح أو التعريف.
جواز التصدُّق ولو باليسِير: كالتَّمرة أو اللُّقمة؛ فإنَّها وِقاية من النار.', 'ليس المِسْكِين : المراد بهذا النفي ليس المحتاج الممدوح الأحق بالصدقة، والمسكين أشد حاجة من الفقير؛ لأن المسكين لا يملك شيئًا بخلاف الفقير، فيملك نصابا غير تام يلبي حاجته.
الَّذِي يَتَعَفَّف : يترك سؤال الناس مع فقره وحاجته.
ولا يُفْطَنُ بِهِ : لا يُعْلَم، ولا يُتَنَبه له.
يُغنِيه : يكفيه عن سؤال الغير.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3141', false),
(20265, 2, 201, 265, 'hadith', 'وعنه عن النبي صلى الله عليه وسلم: " الساعي على الأرملة والمسكين كالمجاهد في سبيل الله" وأحسبه قال: " وكالقائم الذي لا يفتر، وكالصائم الذي لا يفطر".', 'The Prophet (ﷺ) said, "One who strives to help the widows and the poor is like the one who fights in the way of Allah." The narrator said: I think that he (ﷺ) added also: "I shall regard him as the one who stands up (for prayer) without rest and as the one who observes fasts continuously"..', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 265', 'Riyad as-Salihin 265', 'ریاض الصالحین 265', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20266, 2, 201, 266, 'hadith', 'وعنه عن النبي صلى الله عليه وسلم قال: « شر الطعام طعام الوليمة، يمنعها من يأتيها، ويدعى إليها من يأباها، ومن لم يجب الدعوة فقد عصى الله ورسوله».', 'The Prophet (ﷺ) said, "The worst food is the food of the marriage banquet from which those are left out who would like to come; and to which those are invited who refuse to come. He who rejects an invitation disobeys Allah and His Messenger"..', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 266', 'Riyad as-Salihin 266', 'ریاض الصالحین 266', 'رواه مسلم)). وفي رواية في " الصحيحين" عن أبي هريرة من قوله: " بئس الطعام طعام الوليمة يدعى إليها الأغنياء ويترك الفقراء"((متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20267, 2, 201, 267, 'hadith', 'عن أنس رضي الله عنه عن النبي صلى الله عليه وسلم قال: «من عال جاريتين حتى تبلغا جاء يوم القيامة أنا وهو كهاتين» وضم أصابعه.((رواه مسلم)). (29)', 'The Prophet (ﷺ) said, "Whoever supports two girls till they attain maturity, he and I will come on the Day of Resurrection like this". Messenger of Allah (ﷺ) joined his fingers illustrating this..', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 267', 'Riyad as-Salihin 267', 'ریاض الصالحین 267', null, 'أَخْبَرَ النبيُّ صلى الله عليه وسلم أنَّ مَن رُزِقَ باثنتين من البنات أو الأخوات، فقام عليهما بالمُؤنة والتربية والتوجيه للخير والتحذير من الشر ونحو ذلك حتى يَكْبُرَا ويَبْلُغا؛ جاء يوم القيامة هو والنبيُّ صلى الله عليه وسلم كهاتَين وضَمّ أصابِعَه السبابة والوسطى.', 'الثواب العظيم لمن قام على البنات بالمؤونة والتربية حتى يتزوجْن أو يبلغْن، وكذلك الأخوات.
أجر القيام على البنات أعظم من أجر القيام على البنين؛ إذ لم يُذْكَر مثل ذلك في حقِّهم؛ وذلك لأجل أنَّ مؤنة البنات والاهتمام بأمورهن أعظم من أمور البنين؛ لأنهن عورات لا يباشِرْن أمورَهن، ولا يتصرفن تصرف البنين، وكذلك لأنهن لا يتعلق بهن طمع الأب بالاستقواء بهن على الأعداء، وإحياء اسمه واتصال نسبه، وغير ذلك، كما يتعلق بالذكر؛ فاحتيج في ذلك إلى الصبر والإخلاص من المنفق عليهن مع حسن النية؛ فعظم الأجر، فكان رفيق النبي صلى الله عليه وسلم يوم القيامة.
علامات البلوغ للمرأة: إكمال خمس عشرة سنة، أو تحيض ولو قبل خمس عشرة سنة، أو نَبَتتْ لها العانة وهو الشعر الخشن حول القُبُل، أو بالاحتلام وهو إنزال المني في المنام.
قال القرطبي: ويعني ببلوغهما وصولَهما إلى حال يستقلّان بأنفسهما؛ وذلك إنما يكون في النساء إلى أن يدخل بهن أزواجهن، فلا يعني به بلوغهما إلى أن تحيض وتُكلَّف؛ إذ قد تتزوج قبل ذلك فتستغني بالزوج عن قيام الكافل، وقد تحيض وهي غير مستقلة بشيء من مصالحها ولو تركت لضاعت وفسدت أحوالها، بل هي في هذه الحالة أحق بالصيانة والحفظ والقائم عليها لتكمل صيانتها فيرغب في تزويجها، ولهذا المعنى قال علماؤنا لا تسقط النفقة عن والد الصبية ببلوغها بل بدخول الزوج بها.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3360', false),
(20268, 2, 201, 268, 'hadith', 'عن عائشة رضي الله عنها قالت: "دخلت علي امرأة ومعها ابنتان لها تسأل ، فلم تجد عندي شيئا غير تمرة واحدة، فأعطيتها إياها فقسمتها بين ابنتيها ولم تأكل منها، ثم قامت فخرجت، فدخل النبي صلى الله عليه وسلم علينا، فأخبرته فقال: "من ابتلي من هذه البنات بشيء فأحسن إليهن كن له سترًا من النار".', 'A woman came to me with her two daughters. She asked me (for charity) but she found nothing with me except one date-fruit, so I gave it to her. She accepted it and then divided it between her two daughters and herself ate nothing out of that. She then got up and went out. When Messenger of Allah (ﷺ) came in, and I narrated to him the story, he said, "He who is involved (in the responsibility) of (bringing up) daughters, and he is benevolent towards them, they would become protection for him against Hell-fire"..', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 268', 'Riyad as-Salihin 268', 'ریاض الصالحین 268', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20269, 2, 201, 269, 'hadith', 'عن عائشة رضي الله عنها قالت: جاءتني مسكينة تحمل ابنتين لها، فأطعمتها ثلاث تمرات، فأعطت كل واحدة منهما تمرة ورفعت إلى فيها تمرة لتأكلها ، فاستطعمتها ابنتاها، فشقت التمرة التي كانت تريد أن تأكلها بينهما، فأعجبني شأنها، فذكرت الذي صنعت لرسول الله صلى الله عليه وسلم فقال: «إن الله قد أوجب لها بها الجنة، أو أعتقها بها من النار».', 'A poor woman came to me carrying her two daughters. I gave her three date-fruits. She gave a date to each of them and then she took up one date-fruit and brought that to her mouth to eat, but her daughters asked her that also. She then divided between them the date-fruit that she intended to eat. This (kind) treatment of her impressed me and I mentioned that to Messenger of Allah (ﷺ) who said, ''Verily, Allah has assured Jannah for her, because of (this act) of her," or said, "He (SWT) has rescued her from Hell- Fire"..', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 269', 'Riyad as-Salihin 269', 'ریاض الصالحین 269', 'رواه مسلم', 'ذكرت أم المؤمنين عائشة رضي الله عنها أن امرأة مسكينة تحمل ابنتين لها سألتْها، فأطعمتها ثلاث تمرات، فأعطت كل واحدة من بنتيها تمرة، ورفعت إلى فمها تمرة لتأكلها، فطلبت ابنتاها التمرة التي كانت تريد أن تأكلها، فشقت التمرة بينهما، فأعجب عائشةَ رضي الله عنه شأنُها، وذكرت الذي صنعت المرأة للنبي صلى الله عليه وسلم، فقال: 

إن الله قد أوجب لها بهذه التمرة الجنة، أو أعتقها بها من النار.', 'فضل الصدقة وإن كانت قليلة، وهي تدل على صدق المؤمن في إيمانه بربِّه وثقته بوعده وفضله.
شِدَّة رحمة الأمهات بالأولاد وخشيتهن عليهم الضياع.
فضل الإيثار على النفس، ورحمة الصغار، ومزيد الإحسان والرفق بالبنات وأن ذلك سبب لدخول الجنة والعتق من النار.
القليل لا يمتنع التصدق به لحقارته، بل ينبغي للمتصدق أن يتصدق بما تيسر له قل أو كثر.
فيه ما كانت عليه بيوت النبي صلى الله عليه وسلم وكيف كانت عيشته وأهله وليس في بيتهم ما يؤكل غير تمرة أو ثلاث تمرات.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3133', false),
(20270, 2, 201, 270, 'hadith', 'عن أبي شريح خويلد بن عمرو الخزاعي رضي الله عنه قال: قال النبي صلى الله عليه وسلم : «اللهم إني أحرج حق الضعيفين اليتيم والمرأة».', 'The Prophet (ﷺ) said, "O Allah, I declare inviolable the rights of two weak ones: the orphans and women"..', 'أبي شريح خويلد بن عمرو الخزاعي رضي الله عنه', 'Abu Shuraih Khuwailid bin ''Amr Al-Khuza''i (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 270', 'Riyad as-Salihin 270', 'ریاض الصالحین 270', 'حديث حسن رواه النسائي بإسناد جيد', null, null, null, 'sunnah.com', null, false, null, false),
(20271, 2, 201, 271, 'hadith', 'عن مصعب بن سعد بن أبي وقاص رضي الله عنهما قال: رأى سعد أن له فضلا على من دونه، فقال النبي صلى الله عليه وسلم: «هل تنصرون وترزقون إلا بضعفائكم».', 'Sa''d considered himself better than his inferiors, so the Prophet (ﷺ) said to him, "You are given help and provision because of your weak ones"..', 'مصعب بن سعد بن أبي وقاص رضي الله عنهما', 'Mus''ab bin Sa''d bin Abu Waqqas (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 271', 'Riyad as-Salihin 271', 'ریاض الصالحین 271', 'رواه البخاري)) هكذا مرسلا، فإن مصعب بن سعد تابعي، ((ورواه الحافظ أبو بكر البرقاني في صحيحه متصلا عن مصعب عن أبيه رضي الله عنه', null, null, null, 'sunnah.com', null, false, null, false),
(20272, 2, 201, 272, 'hadith', 'عن أبي الدرداء عويمر رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «ابغوني في الضعفاء ، فإنما تنصرون، وترزقون بضعفائكم».', 'Messenger of Allah (ﷺ) said, "Seek among your weak ones, for you are given provision and help only because of the weak amongst you.".', 'أبي الدرداء عويمر رضي الله عنه', 'Abud-Darda (May Allah be pleased with him)', null, 'رياض الصالحين 272', 'Riyad as-Salihin 272', 'ریاض الصالحین 272', 'رواه أبو داود بإسناد جيد', null, null, null, 'sunnah.com', null, false, null, false),
(20273, 2, 201, 273, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : "استوصوا بالنساء خيرًا، فإن المرأة خلقت من ضلع، وإن أعوج ما في الضلع أعلاه، فإن ذهبت تقيمه كسرته، وإن تركته، لم يزل أعوج، فاستوصوا بالنساء" ((متفق عليه)). وفي رواية في ((الصحيحين)) : "المرأة كالضلع إن أقمتها كسرتها، وإن استمتعت بها، استمتعت وفيها عوج". وفي رواية لمسلم: "إن المرأة خلقت من ضلع ، لن تستقيم لك على طريقة، فإن استمعت بها وفيها عوج، وإن ذهبت تقيمها كسرتها ، وكسرها طلاقها".', 'Messenger of Allah (ﷺ) said: "Take my advice with regard to women: Act kindly towards women, for they were created from a rib, and the most crooked part of a rib is its uppermost. If you attempt to straighten it; you will break it, and if you leave it alone it will remain crooked; so act kindly toward women"..In another narration of Al-Bukhari and Muslim, Messenger of Allah (ﷺ) said: "A woman is like a rib, if you attempt to straighten it, you will break it; and if you benefit from her, you will do so while crookedness remains in her".In another narration of Muslim, Messenger of Allah (ﷺ) said: ''Woman has been created from a rib and will in no way be straightened for you; so if you want to benefit from her, you will benefit from her while crookedness remains in her. If you attempt to straighten her, you will break her, and breaking her is divorcing her".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 273', 'Riyad as-Salihin 273', 'ریاض الصالحین 273', null, 'أخبر أبو هريرة رضي الله عنه في معاشرة النساء أن النبي صلى الله عليه وسلم قال: اقبلوا هذه الوصية التي أوصيكم بها، وذلك أن تفعلوا خيرًا مع النساء؛ لأن النساء قاصرات في العقول، وقاصرات في الدين، وقاصرات في التفكير، وقاصرات في جميع شؤونهن، فإنهن خلقن من ضلع.
وذلك أن آدم -عليه الصلاة والسلام- خلقه الله من غير أب ولا أم، بل خلقه من تراب، ثم قال له كن فيكون، ولما أراد الله تعالى أن يبث منه هذه الخليقة، خلق منه زوجه، فخلقها من ضلعه الأعوج، فخلقت من الضلع الأعوج، والضلع الأعوج إن استمتعت به استمتعت به وفيه العوج، وإن ذهبت تقيمه انكسر.
فهذه المرأة أيضا إن استمتع بها الإنسان استمتع بها على عوج، فيرضى بما تيسر، وإن أراد أن تستقيم فإنها لن تستقيم، ولن يتمكن من ذلك، فهي وإن استقامت في دينها فلن تستقيم فيما تقتضيه طبيعتها، ولا تكون لزوجها على ما يريد في كل شيء، بل لابد من مخالفة، ولابد من تقصير، مع القصور الذي فيها، فإن ذهبت تقيمها كسرتها وكسرها طلاقها، ومعناه أنك إن حاولت أن تستقيم لك على ما تريد فلا يمكن ذلك، وحينئذ تسأم منها وتطلقها.', 'توجيه لمعاملة النساء بالتسامح والصبر.
رعاية الإسلام بالمرأة، وفي رعايتها محافظة على سلامة المجتمع.
الإشارة إلى أن حواء خلقت من ضلع آدم -عليهما السلام-.
توجيه الرجال بتحمل ما قد يظهر من النساء من تصرفات؛ لأنهم أقدر على الاحتمال والصبر منهن.
أهمية معرفة المربي لطبيعة من أراد تقويمه وتهذيبه، وهذه المعرفة من المعينات على أداء المهام التربوية والدعوية.
تكرار الوصية بالنساء توكيد على ضرورتها؛ وذلك لضعفهن واحتياجهن إلى من يقوم بأمرهن.', 'اسْتَوْصُوا بالنِّساءِ خَيْرًا : اقبلوا وصيتي بالنساء واعملوا بها.
خُلِقَتْ مِنْ ضِلعٍ : أي: خُلِقن خَلْقا فيه اعوجاج تخالف به الرجل.
وَإنَّ أعْوَجَ مَا في الضِّلَعِ أعْلاهُ : مبالغة في إثبات الاعوجاج.
الضلع : الاعوجاج.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3049', false),
(20274, 2, 201, 274, 'hadith', 'عن عبد الله بن زمعة رضي الله عنه ، أنه سمع النبي صلى الله عليه وسلم يخطب، وذكر الناقة والذي عقرها، فقال رسول الله صلى الله عليه وسلم : (إذ انبعث أشقاها) انبعث لها رجل عزيز، عارم منيع في رهطه" ثم ذكر النساء، فوعظ فيهن، فقال : "يعمد أحدكم فيجلد امرأته جلد العبد فلعله يضاجعها من آخر يومه" ثم وعظهم في ضحكهم من الضرطة وقال: "لم يضحك أحدكم مما يفعل؟".', '"When the most wicked man among them went forth (to kill the she-camel).'' (91:12) signifies that a distinguished, wicked and most powerful chief of the people jumped up to kill the she- camel." Then he (ﷺ) made mention of women and said, "Some of you beat your wives as if they were slaves, and then lie with them at the end of the day".Then he (ﷺ) admonished them against laughing at another''s passing of wind, saying, "Why does any of you laugh at another doing what he does himself".', 'عبد الله بن زمعة رضي الله عنه', '''Abdullah bin Zam''ah (May Allah be pleased with him) reported that he heard the Prophet (ﷺ) giving a speech when he mentioned the she- camel (of Prophet Salih) and the man who had killed her. Messenger of Allah (ﷺ) said:', 'صحيح', 'رياض الصالحين 274', 'Riyad as-Salihin 274', 'ریاض الصالحین 274', 'متفق عليه', 'كان صلى الله عليه وسلم يخطب، وسمعه عبد الله بن زمعة، ومن جملة ما خطب أنه سمع النبي ذكر الناقة التي كانت معجزة لنبي الله صالح -على نبينا وعليه أفضل الصلاة والسلام-، وكان من جملة ما ذكره أيضا الذي عقرها، يقال له قُدَار بن سالف والذي كان أشقى القوم، وجاء من أوصافه: أنه قليل المثل، شديد الإفساد، ذو منعة في قومه.
 ثم قال -عليه الصلاة والسلام- في خطبته: "يعمد أحدكم فيجلد امرأته جلد العبد" وهو في العادة ضرب شديد، وفي سياق الحديث استبعاد وقوع الأمرين من العاقل، أن يُبَالِغَ في ضرب امرأته ثم يجامعها من بقية يومه أو ليلته؛ والمجامعة أو المضاجعة إنما تستحسن مع الميل والرغبة في العشرة، والمجلود غالباً ينفر ممن جلده، فوقعت الإشارة إلى ذَمِّ ذلك، وأنه إذا كان ولا بد فليكن التأديب بالضرب اليسير بحيث لا يحصل معه النفور التام، فلا يفرط في الضرب ولا يفرط في التأديب.
ثم (وعظهم) أي: حذَّرهم في (ضحكهم من الضرطة)؛ وذلك لأنه خلاف المروءة، ولما فيه من هتك الحُرمة، وقال في تقبيح ذلك: (لِم يضحك أحدكم مما يفعل؟)؛ وذلك لأنَّ الضحك إنما يكون من الأمر العجيب والشأن الغريب، يبدو أثره على البشرة فيكون التبسم، فإن قوي وحصل معه الصوت كان الضحك، فإن ارتقى على ذلك كانت القهقهة، وإذا كان هذا الأمر معتاداً من كل إنسان فما وجه الضحك من وقوع ذلك ممن وقع منه؟.', 'إخبار رسول الله -صلى الله عليه وسلم- بقصص الماضين.
بيان معجزة صالح -عليه الصلاة والسلام- وهي الناقة.
ينبغي على العالم إذا وعظ الناس أن يذكرهم بسنن الله في الماضيين؛ لما فيها من مواعظ حسنة وذكرى للذاكرين.
عامة الناس تبع لعِلِّيَّة القوم وكبرائهم على الأغلب.
العامة متى رضيت بفساد الخاصة عمَّهم العذاب جميعًا.
إذا لم ينفع الوعظ والهجر في تأديب الزوجة التي يخشى منها النشوز، فليكن التأديب بالضرب اليسير الذي لا يحصل معه النفور التام، كما قال -تعالى-:(فعظوهن واهجروهن في المضاجع واضربوهن).
الإيماء إلى جواز الضرب اليسير للنساء، مع عدم ضرب الوجه، بحيث لا يحصل معه النفور. 
الضحك إنما يحصل في الأمر الغريب العجيب، وأما الأمر المعتاد من كل إنسان؛ فالضحك منه خلاف المروءة، وهتك لحرمة المسلم.
أن المجامعة إنما تستحسن مع الرغبة في العشرة فيستبعد وقوع الضرب الشديد، والمضاجعة في يوم واحد من عاقل.', 'عَقَرَها : نحرها وذبحها.
انْبَعَثَ : قام بسرعة.
رَجُلٌ عَزِيز : قليل المثل.
عَارِم : الشرير المفسد.
مَنِيع : قوي ذو مَنَعَة.
في رَهطِه : في قومه.
امرأته : زوجته
جَلدَ العَبد : أي: مثل ضربه في كونه شديدًا مؤذيًا.
يُضَاجِعُهَا : يجامعها.
وَعَظَهُم فِي ضَحِكِهم مِنَ الضَّرطَة : أي: حذَّرهم النبي -صلى الله عليه وسلم- في خطبته من الضحك عند سماع صوت خروج الريح من الدبر؛ لأن الضحك من ذلك خلاف المروءة، وفيه هتك الحرمة، وهو أمر معتاد من كل إنسان.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3070', false),
(20275, 2, 201, 275, 'hadith', 'عن أبي هريرة رضي الله عنه قال : قال رسول الله صلى الله عليه وسلم : "لا يفرك مؤمن مؤمنة إن كره منها خُلقا رضي منها آخر" أو قال : "غيره".', 'Messenger of Allah (ﷺ) said, "A believer must not hate (his wife) believing woman; if he dislikes one of her characteristics he will be pleased with another"..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 275', 'Riyad as-Salihin 275', 'ریاض الصالحین 275', 'رواه مسلم', 'نَهَى النبيُّ صلى الله عليه وسلم الزوج أن يُبغض زوجتَه بُغضًا يؤدّي إلى ظلمها وتركها والإعراض عنها؛ 
فإن الإنسان مجبول على النقص، وإن كره منها خُلقًا سيئًا، وجد فيها خلقًا آخر حسنًا؛ فيرضى بالحَسَن الذي يوافقه، ويصبر على ما لا يرضى من السيئ، مما يجعله يصبر ولا يكرهها كرهًا يحمله على فراقها.', 'دعوة المؤمن إلى العدل وتحكيم العقل في أي خلاف ينشأ مع زوجته، وعدم اللجوء إلى تحكيم العاطفة والانفعالات المؤقتة.
شأن المؤمن أن لا يبغض المؤمنة بغضًا كليًّا يحمله على فراقها، بل الذي  ينبغي عليه أن يتغاضى عما يكره بما يحب.
الحث على حسن العشرة والصحبة بين الزوجين.
الإيمان داع لمكارم الأخلاق، فلا يخلو المؤمن والمؤمنة من خلق حسن؛ فالإيمان يستلزم وجود خصال محمودة فيهما.', 'لا يفرك: لا يبغض.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3071', false),
(20276, 2, 201, 276, 'hadith', 'عن عمرو بن الأحوض الجشمي رضي الله عنه أنه سمع النبي صلى الله عليه وسلم في حجة الوداع يقول بعد أن حمد الله تعالى، وأثنى عليه وذكر ووعظ، ثم قال: «ألا واستوصوا بالنساء خيرًا فإنما هن عوانٍ عندكم ليس تملكون منهن شيئا غير ذلك إلا أن يأتين بفاحشة مبينة، فإن فعلن فاهجروهن في المضاجع، واضربوهن ضربا غير مبرح، فإن أطعنكم فلا تبغوا عليهن سبيلا، ألا إن لكم على نسائكم حقا، ولنسائكم عليكم حقا، فحقكم عليهن أن لا يوطئن فرشكم من تكرهون، ولا يأذن في بيوتكم لمن تكرهون، ألا وحقهن عليكم أن تحسنوا إليهن في كسوتهن وطعامهن».', '''Amr bin Al-Ahwas Al-Jushami (May Allah be pleased with him) reported that he had heard the Prophet (ﷺ) saying on his Farewell Pilgrimage, after praising and glorifying Allah and admonishing people, "Treat women kindly, they are like captives in your hands; you do not owe anything else from them. In case they are guilty of open indecency, then do not share their beds and beat them lightly but if they return to obedience, do not have recourse to anything else against them. You have rights over your wives and they have their rights over you. Your right is that they shall not permit anyone you dislike to enter your home, and their right is that you should treat them well in the matter of food and clothing"..', 'عمرو بن الأحوض الجشمي رضي الله عنه', null, 'صحيح', 'رياض الصالحين 276', 'Riyad as-Salihin 276', 'ریاض الصالحین 276', 'رواه الترمذي وقال : حديث حسن صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(20277, 2, 201, 277, 'hadith', 'عن معاوية بن حيدة رضي الله عنه قال : قلت يا رسول الله صلى الله عليه وسلم ما حق زوجة أحدنا عليه؟ قال: "أن تطعمها إذا طعمت ، وتكسوها إذا اكتسيت ولا تضرب الوجه، ولا تقبح، ولا تهجر إلا في البيت " حديث حسن رواه أبو داود وقال: معنى "لاتقبح" أي : لا تقل قبحك الله.', 'I asked Messenger of Allah (ﷺ): "What right can any wife demand of her husband?" He replied, "You should give her food when you eat, clothe her when you clothe yourself, not strike her on the face, and do not revile her or separate from her except in the house"..', 'معاوية بن حيدة رضي الله عنه', 'Mu''awiyah bin Haidah (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 277', 'Riyad as-Salihin 277', 'ریاض الصالحین 277', null, 'سُئِلَ النبيُّ صلى الله عليه وسلم ما حقُّ الزوجة على زوجها؟ فذَكر النبيُّ صلى الله عليه وسلم أمورًا، ومنها: 

أولًا: لا تَخُصّ نفسَك بالطعام دونها؛ بل تطعمها كلما أكلتَ وطعمتَ. 

ثانيًا: لا تخص نفسك بالكسوة واللباس، بل تكسوها إذا اكتسيتَ، وإذا اكتسبت واستطعت. 

ثالثًا: لا تُضرب إلا لسبب وحاجة، وإذا احتاج إلى ضربها للتأديب أو لتركها بعض الفرائض فيكون ضربًا غير مُبَرِّح؛ ولا يُضرب الوجه؛ لأن الوجه أعظم الأعضاء وأظهرها ومشتمل على أجزاء شريفة وأعضاء لطيفة. 

رابعًا: لا تَشْتُم أو تقل: قَبَّحَ اللهُ وجهَك؛ فلا تنسبه ولا شيئًا من بدنها إلى القُبْح الذي هو ضد الحُسْن؛ لأن الله تعالى هو صَوَّرَ وجهَ الإنسان وجِسْمَه، وأحسن كل شيء خلقه، وذَمُّ الخِلْقة يعود إلى مَذَمَّة الخَالق والعياذ بالله. 

خامسًا: لا تَهْجُر إلا في المَضْجَع، ولا تَتَحَوَّل عنها، ولا تُحَوِّلها إلى دار أخرى؛ ولعل ذلك فيما يعتاد وقوعه من الهجر بين الزوج والزوجة.', 'حرص الصحابة على معرفة الحقوق التي عليهم أداؤها لغيرهم، ومعرفة الحقوق التي لهم.
 وجوب النفقة والكسوة والسكنى للمرأة على زوجها.
النهي عن التقبيح المعنوي والحسي.
من التقبيح المنهي عنه أن يقول: أنت من قبيلةٍ رديئة، أو من عائلة سيئة، أو ما أشبه ذلك.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/58093', false),
(20278, 2, 201, 278, 'hadith', 'عن أبي هريرة رضي الله عنه قال : قال رسول الله صلى الله عليه وسلم «أكمل المؤمنين إيمانا أحسنهم خُلقا، وخياركم خياركم لنسائهم».', 'Messenger of Allah (ﷺ) said, "The believers who show the most perfect Faith are those who have the best behaviour, and the best of you are those who are the best to their wives"..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 278', 'Riyad as-Salihin 278', 'ریاض الصالحین 278', 'رواه الترمذي وقال : حديث حسن صحيح', 'يُخْبِرُ النبيُّ صلى الله عليه وسلم أنَّ أَكْمَلَ الناس إيمانًا مَن حَسُنَ خُلُقُه، وذلك بطَلَاقَةِ الوجه، وبذل المعروف، وحسن الكلام، وكف الأذى.


وخَيْرَ المؤمنين خيرُهم لنسائِهِ، كزَوجتِه وبَناتِه وأخواتِه وقَريباتِه؛ لأنهن مِن أحقِّ الناس بحُسْنِ الخُلُق.', 'فضيلة الأخلاق الحسنة وأنها من الإيمان.
 العمل من الإيمان، والإيمان يزيد وينقص.
إكرام الإسلام للمرأة والترغيب في الإحسان إليها.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5792', false),
(20279, 2, 201, 279, 'hadith', 'عن إياس بن أبي ذباب رضي الله عنه قال: قال رسول صلى الله عليه وسلم : "لاتضربوا إماء الله" فجاء عمر رضي الله عنه إلى رسول الله صلى الله عليه وسلم ، فقال : ذئرن النساء على أزواجهن، فرخص في ضربهن، فأطاف بآل رسول الله صلى الله عليه وسلم نساء كثير يشكون أزواجهن، فقال رسول الله صلى الله عليه وسلم : "لقد أطاف بآل بيت محمد نساء كثير يشكون أزواجهن ليس أولئك بخياركم".', 'Messenger of Allah (ﷺ) said, "Do not beat Allah''s bondwomen." When ''Umar (May Allah be pleased with him) came to Messenger of Allah (ﷺ) and complained saying: "The women have become very daring towards their husbands," He (ﷺ) gave permission to beat them. Then many women went to the family of the Messenger of Allah (wives) complaining of their husbands, and he (the Prophet (ﷺ)) said, "Many women have gone round Muhammad''s family complaining of their husbands. Those who do so, that is, those who take to beating their wives, are not the best among you"..', 'إياس بن أبي ذباب رضي الله عنه', 'Iyas bin ''Abdullah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 279', 'Riyad as-Salihin 279', 'ریاض الصالحین 279', 'رواه أبو داود بإسناد صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(20280, 2, 201, 280, 'hadith', 'عن عبد الله بن عمرو بن العاص رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال: «الدنيا متاع، وخير متاعها المرأة الصالحة».', 'Messenger of Allah (ﷺ) said, "The world is but a (quick passing) enjoyment; and the best enjoyment of the world is a pious and virtuous woman"..', 'عبد الله بن عمرو بن العاص رضي الله عنهما', '''Abdullah bin ''Amr bin Al-''as (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 280', 'Riyad as-Salihin 280', 'ریاض الصالحین 280', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false)
on conflict (id) do update set collection_id = excluded.collection_id, chapter_id = excluded.chapter_id, number_in_book = excluded.number_in_book, kind = excluded.kind, arabic = excluded.arabic, translation_en = excluded.translation_en, narrator_ar = excluded.narrator_ar, narrator_en = excluded.narrator_en, grade_ar = excluded.grade_ar, reference_ar = excluded.reference_ar, reference_en = excluded.reference_en, reference_ur = excluded.reference_ur, full_ref_ar = excluded.full_ref_ar, explanation_ar = excluded.explanation_ar, benefits_ar = excluded.benefits_ar, word_meanings_ar = excluded.word_meanings_ar, source = excluded.source, source_ref = excluded.source_ref, daily_ok = excluded.daily_ok, review_note = excluded.review_note, deleted = false;

insert into hadith (id, collection_id, chapter_id, number_in_book, kind, arabic, translation_en, narrator_ar, narrator_en, grade_ar, reference_ar, reference_en, reference_ur, full_ref_ar, explanation_ar, benefits_ar, word_meanings_ar, source, source_ref, daily_ok, review_note, deleted) values
(20281, 2, 201, 281, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم :"إذا دعا الرجل امرأته إلى فراشه فلم تأته فبات غضبان عليها لعنتها الملائكة حتى تصبح" ((متفق عليه)). وفي رواية لها "إذا باتت المرأة هاجرة فراش زوجها لعنتها الملائكة حتى تصبح". وفي رواية قال رسول الله صلى الله عليه وسلم : " والذي نفسي بيده ما من رجل يدعو امرأته إلى فراشه فتأبى عليه إلا كان الذي في السماء ساخطًا عليها حتى يرضي عنها".', 'Messenger of Allah (ﷺ) said, "When a man calls his wife to his bed, and she does not respond and he (the husband) spends the night angry with her, the angels curse her until morning"..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 281', 'Riyad as-Salihin 281', 'ریاض الصالحین 281', null, 'في هذا الحديث دلالة أنَّ على المرأة إذا دعاها الرجل إلى حاجته في الجماع أن تجيبه، وإلا عرضت نفسها للعن الملائكة، لكن هذا مقيدٌ بما إذا غضب الزوج كما ورد في رواية البخاري، أما إذا رضي بذلك فلا بأس، وكذلك إذا كان هناك عذر شرعي كما لو كانت مريضة لا تستطيع معاشرته أو كان عليها عذر يمنعها من الحضور إلى فراشه فهذا لا بأس به، وإلا فإنه يجب عليها أن تحضر وأن تجيبه وإذا كان هذا في حق الزوج على الزوجة فكذلك ينبغي للزوج إذا رأى من أهله أنهم يريدون التمتع فإنه ينبغي أن يجيبهم ليعاشرها كما تعاشره فإن الله تعالى قال: (وعاشروهن بالمعروف).', 'عِظم حق الزوج على زوجته، وأنه يجب له عليها السمع والطاعة في المعروف.
أنَّه يحرم على المرأة أن تمتنع أو تماطل أو تتكرَّه على زوجها إذا دعاها إلى فراشه من أجل الجماع، وأنَّ امتناعها هذا يُعتبر كبيرةً من كبائر الذنوب؛ فإنَّه يترتب عليه أنَّ الملائكة تلعنها حتى تصبح.
أنَّ العشرة الحسنة والصُحبة الطيبة هي أنْ تسعى المرأة في قضاء حقوق زوجها الواجبة عليها، وتلبية رغباته، وأن تؤديها على أكمل وجه ممكن.
جواز لعن العصاة ولو كانوا مسلمين، لكنه مقيد بكونه لعنًا عامًّا ولا يجوز توجيهه للمعين.
 في الحديث دليل على قبول دعاء الملائكة للآدميين من خير أو شر.', 'دعا الرجل امرأته : أي طلبها.
إلى فراشه : بكسر الفاء، وهو هنا كناية عن الجماع.
لعنتها الملائكة : دعت عليها الملائكة باللعنة.
حتى تصبح : حتى يطلع الصباح، لكن هذا القيد أغلبي، لأن أكثر طلب الجماع يكون في الليل، فإذا طلب الرجل جماع زوجته نهارا وامتنعت يلحقها الوعيد أيضًا.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/58098', false),
(20282, 2, 201, 282, 'hadith', 'عن أبي هريرة رضي الله عنه أيضًا أن رسول الله صلى الله عليه وسلم قال؛ « لا يحل لامرأة أن تصوم وزوجها شاهد إلا بإذنه، ولا تأذن في بيته إلا بإذنه».', 'Messenger of Allah (ﷺ) said, "It is not lawful for a woman to observe (voluntary) fasting without the permission of her husband when he is at home; and she should not allow anyone to enter his house without his permission."..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 282', 'Riyad as-Salihin 282', 'ریاض الصالحین 282', 'متفق عليه وهذا لفظ البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(20283, 2, 201, 283, 'hadith', 'عن ابن عمر رضي الله عنهما عن النبي صلى الله عليه وسلم قال: « كلكم راعٍ، وكلكم مسئول عن رعيته، والأمير راعٍ، والرجل راعٍ على أهل بيته؛ والمرأة راعية على بيت زوجها وولده، فكلكم راعٍ، وكلكم مسؤول عن رعيته».', 'The Prophet (ﷺ) said, "All of you are guardians and are responsible for your subjects. The ruler is a guardian of his subjects, the man is a guardian of his family, the woman is a guardian and is responsible for her husband''s house and his offspring; and so all of you are guardians and are responsible for your subjects.".', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 283', 'Riyad as-Salihin 283', 'ریاض الصالحین 283', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20284, 2, 201, 284, 'hadith', 'عن أبي علي طلق بن علي رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: « إذا دعا الرجل زوجته لحاجته فلتأته وإن كانت على التنور».', 'Messenger of Allah (ﷺ) said, "When a man calls his wife to satisfy his desire, she must go to him even if she is occupied with the oven"..', 'أبي علي طلق بن علي رضي الله عنه', 'Abu ''Ali Talq bin ''Ali (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 284', 'Riyad as-Salihin 284', 'ریاض الصالحین 284', 'رواه الترمذي والنسائي وقال الترمذي. حديث حسن صحيح', 'إذا طلب الرجل امرأته للجماع فيجب عليها أن تجيبه ولو كانت مشغولة شغلًا لا يقوم به غيرها، كأن تكون تخبز أو تطبخ.', 'حق الزوج على الزوجة عظيم فينبغي أن تعد نفسها لذلك.
حث المرأة أن تعمل على إرضاء زوجها وإسعاده بكل ما يحبه في غير معصية الله -تعالى-.
الأمور تتفاوت في الأهمية.', 'حاجته : أي: الجماع.
فلتأته : أي لتجب حاجته.
التنور : الذي يخبز فيه الخبز.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5788', false),
(20285, 2, 201, 285, 'hadith', 'عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال: « لو كنت آمرًا أحدًا أن يسجد لأحد لأمرت المرأة أن تسجد لزوجها».', 'The Prophet (ﷺ) said, "If I were to order anyone to prostrate himself before another, I would have ordered a woman to prostrate herself before her husband".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 285', 'Riyad as-Salihin 285', 'ریاض الصالحین 285', 'رواه الترمذي وقال : حديث حسن صحيح', 'أخبر النبي صلى الله عليه وسلم أنه لو كان آمراً أحداً أن يسجد لأحدٍ لأمر الزوجة أن تسجد لزوجها، وذلك تعظيماً لحقه عليها ولكن السجود لغير الله محرم لا يجوز مطلقاً.', 'السجود عبادة لا تنبغي إلا لله وحده.
بيان عظم حق الزوج على الزوجة فهو بعد حق الله عليها.
من سجد لغير الله فقد أشرك.', 'السجود : كمال الانقياد بالهويّ للأرض كما يفعل المصلي.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5826', false),
(20286, 2, 201, 286, 'hadith', 'عن أم سلمة رضي الله عنها قالت: قال رسول الله صلى الله عليه وسلم : « أيما امرأة ماتت، وزوجها عنها راضٍ دخلت الجنة».', 'Messenger of Allah (ﷺ) said, "Any woman dies while her husband is pleased with her, she will enter Jannah"..', 'أم سلمة رضي الله عنها', 'Umm Salamah (May Allah be pleased with her)', 'حسن', 'رياض الصالحين 286', 'Riyad as-Salihin 286', 'ریاض الصالحین 286', 'رواه الترمذي وقال حديث حسن', null, null, null, 'sunnah.com', null, false, null, false),
(20287, 2, 201, 287, 'hadith', 'عن معاذ بن جبل رضي الله عنه عن النبي صلى الله عليه وسلم قال: « لا تؤذي امرأة زوجها في الدنيا إلا قالت زوجة من الحور العين لا تؤذيه قاتلك الله! فإنما هو عندك دخيل يوشك أن يفارقك إلينا».', 'The Prophet (ﷺ) said, "Whenever a woman harms her husband in this world (that is without any due right), his wife among the (Houris in Jannah) says: ''You must not harm him. May Allah destroy you! He is only a passing guest with you and is about to leave you to come to us"..', 'معاذ بن جبل رضي الله عنه', 'Mu''adh bin Jabal (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 287', 'Riyad as-Salihin 287', 'ریاض الصالحین 287', 'رواه الترمذي وقال حديث حسن', 'يخبر النبي صلى الله عليه وسلم عن قول الحور العين عن الزوجة التي تؤذي زوجها في الدنيا، فإنما هذا الزوج ضيف ونزيل في الدنيا يوشك أن يرحل منها إلى الآخرة، ويدخل الجنة فيكون من نصيب نساء الآخرة.', 'تحذير المرأة من إيذاء زوجها.
أعد الله للمؤمنين في الجنة أزواجا مطهرة لا يتحملن أن يؤذى المؤمن ولو من زوجته في الدنيا.
الجنة ونعيمها موجود الآن.
الدنيا دار ابتلاء واختبار والآخرة دار جزاء وبقاء.', 'الحور العين : نساء أهل الجنة.
دخيل : ضيف ونزيل.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5822', false),
(20288, 2, 201, 288, 'hadith', 'عن أسامة بن زيد رضي الله عنهما عن النبي صلى الله عليه وسلم قال: « ما تركت بعدي فتنة هي أضر على الرجال من النساء».', 'The Prophet (ﷺ) said, "I am not leaving behind me a more harmful trial for men than women"..', 'أسامة بن زيد رضي الله عنهما', 'Usamah bin Zaid (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 288', 'Riyad as-Salihin 288', 'ریاض الصالحین 288', 'متفق عليه', 'يُخْبِرُ النبيُّ صلى الله عليه وسلم أنَّه ما تَرَكَ بعدَه ابتلاءً واختبارًا أضرَّ على الرجال من النساء؛ فإن كانتْ مِن أهلِه فقد يَحصُلُ منه متابعةً لها في مُخالفةِ الشرع، وإن كانت أجنبيةً عنه فباختلاطِه وخَلوتِه بها وما ينتج عن ذلك من مفاسد.', 'على المسلم الحذر من فتنة النساء، وسدُّ كلِّ طريق يوجب الفتنة بها.
ينبغي للمؤمن الاعتصام بالله، والرغبة إليه في السلامة من الفتن.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5830', false),
(20289, 2, 201, 289, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : « دينار أنفقته في سبيل الله، ودينار أنفقته في رقبة، ودينار تصدقت به على مسكين، ودينار أنفقته على أهلك، أعظمها أجرًا الذي أنفقته على أهلك».', 'Messenger of Allah (ﷺ) said, "A dinar you spend in Allah''s way, or to free a slave, or as a charity you give to a needy person, or to support your family, the one yielding the greatest reward is that which you spend on your family"..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 289', 'Riyad as-Salihin 289', 'ریاض الصالحین 289', 'رواه مسلم', 'ذكر النبيُّ صلى الله عليه وسلم بعض أنواع النفقة، فقال: دينار أنفقته في الجهاد في سبيل الله، ودينار أنفقته في عتق رقبة من الرق والعبودية، ودينار تصدقت به على مسكين محتاج، ودينار أنفقته على أهلك وعيالك، ثم أخبر أن أعظمها أجرًا عند الله الذي أنفقته على أهلك وعيالك ومن تلزمك نفقتُه.', 'كثرة أبواب الإنفاق في سبيل الله.
تقديم الأولى في باب الإنفاق عند التزاحم، ومن ذلك النفقة على الأهل عند عدم استطاعة فعل الجميع.
قال النووي على شرح مسلم: الحث على النفقة على العيال، وبيان عظم الثواب فيه؛ لأن منهم من تجب نفقته بالقرابة، ومنهم من تكون مندوبة وتكون صدقة وصلة، ومنهم من تكون واجبة بملك النكاح أو ملك اليمين، وهذا كله فاضل محثوث عليه، وهو أفضل من صدقة التطوع.
قال السندي: قوله (دينار ينفقه على عياله)، أي: إذا نوى به وجه الله وأراد حق العيال مثلًا.
قال أبو قلابة: وأي رجل أعظم أجرًا من رجل ينفق على عيال صغار يعفهم أو ينفعهم الله به ويغنيهم؟!', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5813', false),
(20290, 2, 201, 290, 'hadith', 'عن أبي عبد الله - ويقال له: أبو عبد الرحمن - ثوبان بن بجدد مولى رسول الله صلى الله عليه وسلم قال: قال رسول الله صلى الله عليه وسلم : « أفضل دينار ينفقه الرجل دينار ينفقه على عياله، ودينار ينفقه على دابته في سبيل الله، ودينار ينفقه على أصحابه في سبيل الله».', 'Messenger of Allah (ﷺ) said, "The most excellent dinar is one that a person spends on his family, and the dinar which he spends on his riding-animal in the way of Allah (in Jihad), and the dinar he spends on his companions in the way of Allah"..', null, 'Thauban bin Bujdud (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 290', 'Riyad as-Salihin 290', 'ریاض الصالحین 290', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(20291, 2, 201, 291, 'hadith', 'عن أم سلمة رضي الله عنها قالت: قلت يارسول الله، هل لي أجر في بني أبي سلمة أن أنفق عليهم، ولست بتاركتهم هكذا وهكذا إنما هم بني؟ فقال: « نعم لك أجر ما أنفقت عليهم».', 'I asked Messenger of Allah (ﷺ), "Would I be rewarded for what I spend on Abu Salamah''s sons? For I can''t let them go here and there (to beg people)." Messenger of Allah (ﷺ) replied, "Spend on them and you will be rewarded for what you spend on them"..', 'أم سلمة رضي الله عنها', 'Umm Salamah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 291', 'Riyad as-Salihin 291', 'ریاض الصالحین 291', 'متفق عليه', 'قالت أم سلمة رضي الله عنها لرسول الله صلى الله عليه وسلم: هل لي ثواب أخروي في أني أنفق على عيالي من أبي سلمة وأكفيهم، ولا أدعهم يتفرقون في طلب القوت؟ أم أنه لا أجر لي لأني أفعل ذلك شفقة لأنهم أبنائي؟ فأخبرها النبي صلى الله عليه وسلم أن لها أجرًا في إنفاقها عليهم.', 'بيان حصول الثواب للأم بالإنفاق على أولادها؛ وإن كانت تنفق عليهم بدافع الشفقة والرحمة.
فضل الإنفاق على الأيتام في الحجر.
شدة شفقة الأم على بنيها ورحمتها بهم.
يستحب لولي الأمر ترغيب الرجال والنساء من المسلمين في أفعال الخير.', 'أجر : أي: ثواب أخروي.
بني أبي سلمة : أي: أولادها منه.
بتاركتهم هكذا وهكذا : أي: يتفرقون في طلب القوت يمينًا وشمالاً.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4959', false),
(20292, 2, 201, 292, 'hadith', 'عن سعد بن أبي وقاص رضي الله عنه في حديثه الطويل الذي قدمناه في أول الكتاب في باب النية أن رسول الله صلى الله عليه وسلم قال له: « وإنك لن تنفق تبغي بها وجه الله إلا أجرت بها حتى ما تجعل في في امرأتك».', 'Sa''d bin Abu Waqqas (May Allah be pleased with him) reported in a Hadith included in the chapter of Intention, that Messenger of Allah (ﷺ) said, "Whatever you spend seeking thereby the Pleasure of Allah, will have its reward, even the morsel which you put in the mouth of your wife"..', 'سعد بن أبي وقاص رضي الله عنه', null, 'صحيح', 'رياض الصالحين 292', 'Riyad as-Salihin 292', 'ریاض الصالحین 292', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20293, 2, 201, 293, 'hadith', 'عن أبي مسعود البدري رضي الله عنه، عن النبي صلى الله عليه وسلم قال: « إذا أنفق الرجل على أهله نفقة يحتسبها فهي له صدقة».', 'The Prophet (ﷺ) said, "When someone spends on his family seeking his reward for it from Allah, it is counted as a charity from him"..', 'أبي مسعود البدري رضي الله عنه', 'Abu Mas''ud Al-Badri (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 293', 'Riyad as-Salihin 293', 'ریاض الصالحین 293', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20294, 2, 201, 294, 'hadith', 'عن عبد الله بن عمرو بن العاص رضي الله عنهما قال: رسول الله صلى الله عليه وسلم : " كفى بالمرء إثمًا أن يضيع من يقوت" حديث صحيح ((رواه أبو داود وغيره)). ورواه مسلم في صحيحه بمعناه قال: " كفى بالمرء إثمًا أن يحبس عمن يملك قوته".', 'Messenger of Allah (ﷺ) said, "Neglecting one''s own dependents is a reason enough for a man to commit a sin".The narration in Muslim is: Messenger of Allah (ﷺ) said, "It is enough sin for a person to hold back the due of one whose provision is in his hand".', 'عبد الله بن عمرو بن العاص رضي الله عنهما', '''Abdullah bin ''Amr bin Al-''as (May Allah be pleased with them)', null, 'رياض الصالحين 294', 'Riyad as-Salihin 294', 'ریاض الصالحین 294', null, null, null, null, 'sunnah.com', null, false, null, false),
(20295, 2, 201, 295, 'hadith', 'عن أبي هريرة رضي الله عنه أن النبي صلى الله عليه وسلم قال: « ما من يوم يصبح العباد فيه إلا ملكان ينزلان، فيقول أحدهما: اللهم أعط منفقًا خلفًا، ويقول الآخر: اللهم أعط ممسكًا تلفًا».', 'The Prophet (ﷺ) said, "Two angels descend every morning, and one says: ''O Allah, give him who spends something, in place of what he spends.'' The other one says: ''O Allah, give destruction to him who withholds"..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 295', 'Riyad as-Salihin 295', 'ریاض الصالحین 295', 'متفق عليه', 'أَخْبَرَ النبيُّ صلى الله عليه وسلم أنّه في كلِّ يوم تَطلُع الشمسُ فيه إلّا ومَلَكَان يَنزلان يُناديان، يقول أحدهما: 

اللهم أعط منفقًا في الطاعات وعلى العيال والضِّيْفان والتطوُّعات خَلَفًا وعَوِّضْهُ خيرًا فيما أَنفق، وبارك له. 

ويقول الآخر: اللهم أعط ممسكًا عنها تَلفًا وأَهْلِكْ مالَه الذي مَنعه عن مُسْتَحِقِّيْه.', 'جواز الدعاء للكريم بمزيد من العِوَض، وأن يَخلِف عليه خيرًا مما أَنفق، وجواز الدعاء على البخيل بتَلَف ماله الذي بَخِلَ به ومَنَعَ إنفاقَه فيما أوجب الله عليه.
دعاء الملائكة للمؤمنين الصالحين المنفقين بالخير والبركة، وأنّ دعاءهم مستجاب.
الحضُّ على الإنفاق في الواجبات والتطوعات؛ كالنفقة على الأهل، وصلة الرحم، وأبواب الخير.
بيان فضل المُنفِق في وجوه الخير، وأنّ عاقبته أنّ الله يُخْلِفُ عليه، قال الله تعالى: ﴿وَمَا أَنفَقْتُم مِّن شَيْءٍ فَهُوَ يُخْلِفُهُ وَهُوَ خَيْرُ الرَّازِقِينَ﴾ [سبأ: 39].
هذا الدعاء على المُمسك عن النفقات الواجبة، وأما النفقات المستحبة فلا تدخل؛ لأن صاحبها لا يستحق هذا الدعاء.
تحريم البخل والشُّحّ.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3379', false),
(20296, 2, 201, 296, 'hadith', 'وعنه عن النبي صلى الله عليه وسلم قال: « اليد العليا خير من اليد السفلى وابدأ بمن تعول، وخير الصدقة ما كان عن ظهر غنًى، ومن يستعفف، يعفه الله، ومن يستغن، يغنه الله».', 'The Prophet (ﷺ) said, "The upper hand is better than the lower one (i.e., the spending hand is better than the receiving hand); and begin (charity) with those who are under your care; and the best charity is that which given out of surplus; and he who asks (Allah) to help him abstain from the unlawful and the forbidden, Allah will fulfill his wish; and he who seeks self-sufficiency will be made self-sufficient by Allah"..', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 296', 'Riyad as-Salihin 296', 'ریاض الصالحین 296', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(20297, 2, 201, 297, 'hadith', 'عن أنس رضي الله عنه قال: كان أبو طلحة رضي الله عنه أكثر الأنصار بالمدينة مالاً من نخل، وكان أحب أمواله إليه بيرحاء، وكانت مستقبلة المسجد، وكان رسول الله صلى الله عليه وسلم يدخلها ويشرب من ماء فيها طيب قال أنس: فلما نزلت هذه الآية: {لن تنالوا البر حتى تنفقوا مما تحبون} قام أبو طلحة إلى رسول الله صلى الله عليه وسلم فقال: يارسول إن الله تعالى أنزل عليك: { لن تنالوا البر حتى تنفقوا مما تحبون} وإن أحب مالي إلي بيرحاء، وإنها صدقة لله تعالى أرجو برها وذخرها عند الله تعالى، فضعها يا رسول الله حيث أراك الله، فقال رسول الله صلى الله عليه وسلم : « بخٍ! ذلك مال رابح، ذلك مال رابح، وقد سمعت ما قلت، وإني أرى أن تجعلها في الأقربين» فقال أبو طلحة: أفعل يا رسول الله، فقسمها أبو طلحة في أقاربه، وبني عمه.', 'Abu Talhah (May Allah be pleased with him) was the richest among the Ansar of Al-Madinah and possessed the largest property from palm-trees, and among his possessions what he loved most, was his garden known as Bairuha'' which was opposite the mosque, and Messenger of Allah (ﷺ) often visited it and drank from its fresh water. When this Ayah was revealed: "By no means shall you attain Al-Birr (piety, righteousness - here it means Allah''s reward, i.e., Jannah), unless you spend (in Allah''s Cause) of that which you love," (3:92), Abu Talhah came to Messenger of Allah (ﷺ) and said, "Allah says in His Book: ''By no means shall you attain Al-Birr, unless you spend (in Allah''s Cause) of that which you love,'' and the dearest of my property is Bairuha'' so I have given it as Sadaqah (charity) for Allah''s sake, and I anticipate its reward with Him; so spend it, O Messenger of Allah, as Allah guides you." Messenger of Allah (ﷺ) said, "Well-done! That is profit earning property. I have heard what you have said, but I think you should spend it on your nearest relatives." So Abu Talhah (May Allah be pleased with him) distributed it among nearest relatives and cousins..', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 297', 'Riyad as-Salihin 297', 'ریاض الصالحین 297', 'متفق عليه', 'كان أبو طلحة رضي الله عنه أكثر الأنصار بالمدينة مزارع، وكان له بستان في قبلة المسجد فيه ماء طيب، وكان النبي صلى الله عليه وسلم يأتيه ويشرب منه، فلما نزل قوله تعالى : (لَنْ تَنَالُوا الْبِرَّ حَتَّى تُنْفِقُوا مِمَّا تُحِبُّونَ) بادر رضي الله عنه وسابق وسارع وجاء إلى النبي صلى الله عليه وسلم وقال: يا رسول الله، إن الله تعالى أنزل قوله: (لَنْ تَنَالُوا الْبِرَّ حَتَّى تُنْفِقُوا مِمَّا تُحِبُّونَ) وإن أحب أموالي إلي بيرحاء -وهذا اسم ذلك البستان- وإني جعلتها بين يديك صدقة لله ورسوله؛ فقال النبي صلى الله عليه وسلم متعجبًا: بخ بخ ذاك مال رابح، ذاك مال رابح، أرى أن تجعلها في أقاربك. ففعل رضي الله عنه ، وقسمها في أقاربه وبني عمه.', 'فضل الإنفاق من أحسن أموال العبد وأحبها إلى نفسه.
جواز دخول أهل العلم والفضل البساتين ليستظلوا بظلها، ويأكلوا من ثمرها، ويستريحوا فيها، وخاصة إذا كان أصحابها يُسرون بذلك.
فضل الصحابة رضي الله عنهم، وسرعة استجابتهم لأمر الله -تعالى-، وحرصهم على بلوغ أعلى درجات الكمال.
تفويض أهل الفضل بتوزيع الصدقات في وجوه الخير.
التشجيع على فعل الخير بالثناء على الفاعل، وشكره على عمله وإظهار الرضا والسرور به.
أولى الناس بالإحسان إليهم ذوو الأرحام، ثم من دونهم إذا كانوا محتاجين.
فيه فضيلة لأبي طلحة واسمه زيد بن سهل -رضي الله عنه-.
ما يقدمه العبد بين يديه عند مولاه، ويدخره ليوم لا ينفع فيه مال ولا بنون هو المال الرابح.', 'الأنصار	. : أهل مدينة رسول الله -صلى الله عليه وسلم- الذين ناصروه حين هاجر إليهم.
بيرحاء : اسم حديقة نخل.
مستقبلة المسجد : أي: أمام المسجد النبوي.
طيب : عذب.
بِرها : خيرها.
ذخرها : نفعها وقت حاجتي إليها.
فضعها : اجعلها، أي: أفوض أمرها إليك.
بخ : كلمة تقال عند الرضا بالشيء، تفخيما له وإعجابا به.
رابح : أي: راجع وعائد.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4290', false),
(20298, 2, 201, 298, 'hadith', 'عن أبي هريرة رضي الله عنه قال: أخذ الحسن بن على رضي الله عنهما تمرة الصدقة فجعلها في فيه فقال رسول الله صلى الله عليه وسلم: " كخ كخ، ارم بها، أما علمت أنَّا لا نأكل الصدقة!؟ ((متفق عليه)). وفي رواية" أنَّا لا تحل لنا الصدقة" وقوله: " كخٍْ كخٍْ" يقال بإسكان الخاء، ويقال بكسرها مع التنوين، وهي كلمة زجر للصبي عن المستقذرات. وكان الحسن رضي الله عنه صبيًا.', 'Al-Hasan bin ''Ali (May Allah be pleased with them) took one of the dates of the Sadaqah (charity) and put it in his mouth, whereupon Messenger of Allah (ﷺ) said, "Leave it, leave it, throw it away. Do you not know that we do not eat the Sadaqah (charity)?".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 298', 'Riyad as-Salihin 298', 'ریاض الصالحین 298', null, 'أخذ الحسن بن علي رضي الله عنهما تمرة مما جمع من زكاة التمر فوضعها في فمه، فقال النبي صلى الله عليه وسلم : "كخ كخ" يعني أنها لا تصلح لك، ثم أمره أن يخرجها من فمه، وقال: "إننا لا تحل لنا الصدقة".
فالصدقة لا تحل لآل محمد؛ وذلك لأنهم أشرف الناس، والصدقات والزكوات أوساخ الناس، ولا يناسب لأشراف الناس أن يأخذوا أوساخ الناس، كما قال النبي صلى الله عليه وسلم لعمه العباس بن عبد المطلب رضي الله عنه : "إنا آل محمد لا تحل لنا الصدقة؛ إنما هي أوساخ الناس".', 'وجوب توجيه الإنسان لأفراد أسرته ومن في رعايته، ومنعهم من المحرمات مع بيان الحكمة من ذلك.
تحريم الصدقات والزكاة على آل البيت.
على ولي الأمر أن يقوم بجمع الزكاة ويدفعها إلى مستحقيها، ويرعى ذلك بدقة وأمانة بالغتين.
مشروعية دفع الصدقات للإمام.
استحباب الإعلام بسبب النهي والزجر.
جواز مخاطبة من لا يميز لقصد إسماع من يميز.
استحباب استخدام اللفظ المعقول للمخاطب؛ لأنه من باب: حدثوا الناس على قدر عقولهم.', 'تمر الصدقة : ما جُمع من زكاة التمر، والزكاة في الاصطلاح: تطلق على أداء حق يجب في أموال مخصوصة على وجه مخصوص، ويعتبر في وجوبه الحول والنصاب.
كخ كخ : كلمة زجر للصبي عن المستقذراتِ، وكان الحسن -رضي الله عنه- صبِيًّا.
لنا : أي: آل محمد -صلى الله عليه وسلم-، والمراد بنو هاشم وبنو عبد المطلب.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/10102', false),
(20299, 2, 201, 299, 'hadith', 'عن أبي حفص عمر بن أبي سلمة عبد الله بن عبد الأسد ربيب رسول الله صلى الله عليه وسلم قال: كنت غلامًا في حجر رسول الله صلى الله عليه وسلم وكانت يدي تطيش في الصحفة، فقال لي رسول الله صلى الله عليه وسلم : « يا غلام سَمِّ الله تعالى، وكُل بيمينك، وكُل مما يليك» فما زالت تلك طعمتي بعد.', 'I was a boy under the care of Messenger of Allah (ﷺ), and my hand would wander about in the dish. Messenger of Allah (ﷺ) said to me "Mention Allah''s Name (i.e., say Bismillah before you start eating), eat with your right hand and eat from what is near to you". I always followed this way of eating after this incident..', null, '''Umar bin Abu Salamah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 299', 'Riyad as-Salihin 299', 'ریاض الصالحین 299', 'متفق عليه', 'يُخْبِرُ عُمَرُ بن أبي سلمة رضي الله عنهما، ابن زوجة النبي صلى الله عليه وسلم أم سلمة رضي الله عنها، -وكان تحت تربيتِه ورعايته-، أنه كان أثناء الأكل يَنْقُلُ يدَه في جوانب الإناء ليلتقط الطعام، فعلَّمه النبي صلى الله عليه وسلم ثلاثة آداب من آداب الأكل: 

أولها: قول "بسم الله" في بداية الأكل. 

وثانيها: الأكل باليمين. 

وثالثها: الأكل من الجانب الذي يَقْرُبُ منه من الطعام.', 'من آداب الأكل والشرب التسميةُ في أوله.
تعليم الصبيان الآداب، لاسيَّما من كان تحت كفالة الإنسان.
رفق النبي صلى الله عليه وسلم، وسعة صدره في تعليم الصغار وتأديبهم.
من آداب الطعام الأكل مما يلي الإنسان، إلا إذا كان أصنافًا متعددة فله أن يأخذ منها.
التزام الصحابة بما أدَّبهم به النبي صلى الله عليه وسلم، وذلك مستفاد من قول عمر: فما زالت تلك طعمتي بعد.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/58120', false),
(20300, 2, 201, 300, 'hadith', 'عن ابن عمر رضي الله عنهما قال: سمعت رسول الله صلى الله عليه وسلم يقول: كلكم راعٍ، وكلكم مسئول عن رعيته، والمرأة راعية في بيت زوجها ومسئولة عن رعيتها، والخادم راعٍ في مال سيده ومسئول عن رعيته، فكلكم راعٍ ومسئول عن رعيته".', 'Messenger of Allah (ﷺ) said, "All of you are guardians and are responsible for your subjects. The ruler is a guardian and responsible for his subjects; the man is a guardian of his family; the woman is guardian in her husband''s house and responsible for her wards; a servant is guardian of his master''s property and responsible for his ward. So all of you are guardians and are responsible for your subjects"..', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 300', 'Riyad as-Salihin 300', 'ریاض الصالحین 300', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20301, 2, 201, 301, 'hadith', 'عن عمرو بن شعيب، عن أبيه، عن جده رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : « مروا أولادكم بالصلاة وهم أبناء سبع سنين، واضربوهم عليها، وهم أبناء عشر، وفرقوا بينهم في المضاجع».', 'Messenger of Allah (ﷺ) said, "Command your children to perform Salat (prayer) when they are seven years old, and beat them for (not offering) it when they are ten, and do not let (boys and girls) sleep together"..', 'عمرو بن شعيب، عن أبيه، عن جده رضي الله عنه', '''Amr bin Shu''aib reported on his father''s authority that his grandfather (May Allah be pleased with him) said:', 'حسن', 'رياض الصالحين 301', 'Riyad as-Salihin 301', 'ریاض الصالحین 301', 'حديث حسن رواه أبو داود بإسناد حسن', 'بَيَّنَ النبيُّ صلى الله عليه وسلم أنَّ على الأبِ أنْ يأمُرَ أولادَه -الذكور والإناث- بالصلاة وأعمارهم سبع سنين، ويُعَلِّمهم ما يحتاجون لإقامتها. 
وإذا بَلَغُوا عشرَ سنين زادَ في الأمر، فيضرب على التقصير فيها، ويُفَرِّق بينهم في الفِراش.', 'تعليم الأولاد الصغار قبل البلوغ أمورَ الدين، ومن أهمِّها الصلاة.
الضرب يكون للتأديب، وليس للتعذيب، فيضرب ضربًا يليق بحالِه.
عناية الشريعة بحفظ الأعراض، وسدُّها كلَّ طريقٍ قد يُفضي إلى الفساد.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5272', false),
(20302, 2, 201, 302, 'hadith', 'عن أبي ثرية سبرة بن معبد الجهني رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : " علموا الصبي الصلاة لسبع سنين" واضربوه عليها ابن عشر سنين" حديث حسن رواه أبو داود، والترمذي وقال حديث حسن. ولفظ أبي داود: " مروا الصبي بالصلاة إذا بلغ سبع سنين".', 'Messenger of Allah (ﷺ) said, "Teach a boy Salat (the prayer) when he attains the age of seven years, and punish him (if he does not offer it) at ten"..The narration in Abu Dawud is: Messenger of Allah (ﷺ) said, "Order a boy to perform Salat (the prayer) when he is seven years old".', 'أبي ثرية سبرة بن معبد الجهني رضي الله عنه', 'Sabrah bin Ma''bad Al-Juhani (May Allah be pleased with him)', null, 'رياض الصالحين 302', 'Riyad as-Salihin 302', 'ریاض الصالحین 302', null, null, null, null, 'sunnah.com', null, false, null, false),
(20303, 2, 201, 303, 'hadith', 'عن ابن عمر وعائشة رضي الله عنهما قالا: قال رسول الله صلى الله عليه وسلم : « ما زال جبريل يوصيني بالجار حتى ظننت أنه سيورثه».', 'Messenger of Allah (ﷺ) said, "Jibril kept recommending treating neighbours with kindness until I thought he would assign a share of inheritance"..', 'ابن عمر وعائشة رضي الله عنهما', 'Ibn ''Umar and ''Aishah (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 303', 'Riyad as-Salihin 303', 'ریاض الصالحین 303', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20304, 2, 201, 304, 'hadith', 'عن أبي ذر رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : "يا أبا ذر إذا طبخت مرقة، فأكثر ماءها، وتعاهد جيرانك" ((رواه مسلم)). وفي رواية له عن أبي ذر قال: إن خليلي صلى الله عليه وسلم أوصاني: " إذا طبخت مرقًا فأكثر ماءها، ثم انظر أهل بيت من جيرانك، فأصبهم منها بمعروف".', 'Messenger of Allah (ﷺ) commanded me thus, "O Abu Dharr! Whenever you prepare a broth, put plenty of water in it, and and give some of it to your neighbours"..In another narration of Muslim, narrated Abu Dharr (May Allah be pleased with him): My friend, (Messenger of Allah (ﷺ)) advised me saying, "Whenever you prepare a broth, put plenty of water in it, and give some to your neighbours and then give them out of this with courtesy."', 'أبي ذر رضي الله عنه', 'Abu Dharr (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 304', 'Riyad as-Salihin 304', 'ریاض الصالحین 304', null, 'حثّ النبيُّ صلى الله عليه وسلم أبا ذر الغفاري رضي الله عنه إذا طبخ مرقة أن يكثر ماءها ومرقها، ويتعاهد ويتفقَّد به جيرانه.', 'الحث على حسن المعاملة مع الجيران.
استحباب التهادي بين الجيران؛ لأن ذلك يورث المحبة ويزيد في المودة، ويتأكد هذا التهادي إذا كان للطعام رائحة، وعُلمت حاجة الجار.
الحث على بذل المعروف وما تيسّر منه وإن قَلّ، وإدخال السرور على المسلمين.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5336', false),
(20305, 2, 201, 305, 'hadith', 'عن أبي هريرة رضي الله عنه أن النبي صلى الله عليه وسلم قال: " والله لا يؤمن، والله لايؤمن، والله لا يؤمن!" قيل: من يا رسول الله؟ قال: " الذي لا يأمن جاره بوائقه ! " ((متفق عليه)). وفي رواية لمسلم: " لايدخل الجنة من لا يأمن جاره بوائقه".', 'The Prophet (ﷺ) said, "By Allah, he is not a believer! By Allah, he is not a believer! By Allah, he is not a believer." It was asked, "Who is that, O Messenger of Allah?" He said, "One whose neighbour does not feel safe from his evil"..Another narration of Muslim is: Messenger of Allah (ﷺ) said, "He will not enter Jannah whose neighbour is not secure from his wrongful conduct".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', null, 'رياض الصالحين 305', 'Riyad as-Salihin 305', 'ریاض الصالحین 305', null, null, null, null, 'sunnah.com', null, false, null, false),
(20306, 2, 201, 306, 'hadith', 'وعنه قال: قال رسول الله صلى الله عليه وسلم : « يا نساء المسلمات لا تحقرن جارة لجارتها ولو فرسن شاة».', 'Messenger of Allah (ﷺ) said, "O Muslim women! No one of you should consider insignificant (a gift) to give to her neighbour even if it is (a gift of) the trotters of a sheep"..', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 306', 'Riyad as-Salihin 306', 'ریاض الصالحین 306', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20307, 2, 201, 307, 'hadith', 'وعنه أن رسول الله صلى الله عليه وسلم قال: « لا يمنع جار جارة أن يغرز خشبة في جداره» ثم يقول أبو هريرة: ما لي أراكم عنها معرضين! والله لأرمين بها بين أكتافكم.', 'Messenger of Allah (ﷺ) said, "No one should prohibit his neighbour from placing a peg in his wall". Abu Hurairah (May Allah be pleased with him) added: Now I see you turning away from this (Sunnah), but by Allah, I shall go on proclaiming it..', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 307', 'Riyad as-Salihin 307', 'ریاض الصالحین 307', 'متفق عليه', 'للجار على جاره حقوق تجب مراعاتها، فقد حث النبي صلى الله عليه وسلم على صلة الجار، وذكر أن جبريل مازال يوصيه به حتى ظن أنه سيورثه من جاره، لعظم حقه، وواجب بره.
فلهذا تجب بينهم العشرة الحسنهَ، والسيرة الحميدة، ومراعاة حقوق الجيرة، وأن يكف بعضهم عن بعض الشر القولي والفعلي. 
ومن حسن الجوار ومراعاة حقوقه أن يبذل بعضهم لبعض المنافع التي لا تعود عليهم بالضرر الكبير مع نفعها للجار.
ومن ذلك أن يريد الجار أن يضع خشبة في جدار جاره، فإن وجدت حاجة لصاحب الخشب، وليس على صاحب الجدار ضرر من وضع الخشب، فيجب على صاحب الجدار أن يأذن له في هذا الانتفاع الذي ليس عليه منه ضرر مع حاجة جاره إليه، ويجبره الحاكم على ذلك إن لم يأذن.
فإن كان هناك ضرر أو ليس هناك حاجة فالضرر لا يزال بضرر مثله، والأصل في حق المسلم المنع، فلا يجب عليه أن يأذن.
ولذا فإن أبا هريرة رضي الله عنه ، لما علم مراد المشرع الأعظم من هذه السنة الأكيدة، استنكر منهم إعراضهم في العمل بها، وتوعدهم بأن يلزمهم بالقيام بها، فإن للجار حقوقا فرضها اللَه تعالى تجب مراعاتها والقيام بها.
وقد أجمع العلماء على المنع من وضع خشب الجار على جدار جاره مع وجود الضرر إلا بإذنه لقوله -عليه الصلاة والسلام-: " لا ضرر ولا ضرار ".', 'النهْي عن منع الجار أن يضع خشبة على جدار جاره، إذا لم يكن عليه ضرر من وضعها، وكان في الجار حاجة إلى ذلك.
قيد وضع الخشب بعدم الضرر على صاحب الجدار، وبحاجة صاحب الخشب، لأن التصرف في مال الغير ممنوع إلا بإذنه، فلا يجوز إلا لحاجة من عليه له الحق وهو الجار،كما أنه لا يوضع مع تضرره لأًن الضرر لا يزال بالضرر.
فهم أبو هريرة -رضي اللَه عنه- أن الجار متحتم عليه بَذْلُ ذلك لجاره، ولذلك فإنه استنكر عليهم إعراضهم عن هذه السنة، لكنه من باب التأكيد على فعلها وعدم تركها.
الشارع الحكيم عظَّم حق الجار وحثَّ على الإحسان إليه، في جميع صور البر والإحسان وتمكينه من المنافع التي لا ضرر فيها.', 'لايمنعن : لا: ناهية، والفعل بعدها مجزوم بها.
جار : المراد بالجار هنا الملاصق والقريب.
خشبة : بالإفراد، وقد روي بالجمع، والمعنى واحد.
ثم يقول أبو هريرة : قائل ذلك هو الأعرج، وهو الراوي عن أبي هريرة -رضي الله عنه-.
عنها : عن هذه السنة أو عن هذه المقالة.
لأرمين بها : لأشيعن هذه المقالة فيكم.
بين أكتافكم : بالتاء المثناة الفوقية، جمع: كتف، ويروى بالنون: "أكنافكم" جمع كنف، بمعنى الجانب.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6094', false),
(20308, 2, 201, 308, 'hadith', 'وعنه أن رسول الله صلى الله عليه وسلم قال: « من كان يؤمن بالله واليوم الآخر، فلا يؤذِ جاره، ومن كان يؤمن بالله واليوم الآخر، فليكرم ضيفه، ومن كان يؤمن بالله واليوم الآخر، فليقل خيرًا أو ليسكت».', 'Messenger of Allah (ﷺ) said, "He who believes in Allah and the Last Day let him not harm his neighbour; and he who believes in Allah and the Last Day let him show hospitality to his guest; and he who believes in Allah and the Last Day let him speak good or remain silent"..', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 308', 'Riyad as-Salihin 308', 'ریاض الصالحین 308', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20309, 2, 201, 309, 'hadith', 'عن أبي شريح الخزاعي رضي الله عنه أن النبي صلى الله عليه وسلم قال: « من كان يؤمن بالله واليوم الآخر، فليكرم ضيفه، ومن كان يؤمن بالله واليوم الآخر، فليقل خيرًا أو ليسكت».', 'The Prophet (ﷺ) said, "He who believes in Allah and the Last Day, let him be kind to his neighbour; and he who believes in Allah and the Last Day, let him show hospitality to his guest; and he who believes in Allah and the Last Day, let him either speak good or remain silent"..', 'أبي شريح الخزاعي رضي الله عنه', 'Abu Shuraih Al-Khuza''i (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 309', 'Riyad as-Salihin 309', 'ریاض الصالحین 309', 'رواه مسلم بهذا اللفظ، وروى البخاري بعضه', null, null, null, 'sunnah.com', null, false, null, false),
(20310, 2, 201, 310, 'hadith', 'عن عائشة رضي الله عنها قالت: قلت: يارسول الله إن لي جارين، فإلى أيهما أُهْدِي؟ قال: « إلى أقربهما منك بابًا».', 'I said, "O Messenger of Allah (ﷺ), I have two neighbours, to which of them should I send a present?" He (ﷺ) replied, "To the one whose door is nearer to you".', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 310', 'Riyad as-Salihin 310', 'ریاض الصالحین 310', 'رواه البخاري', 'سألت عائشة رضي الله عنها النبي صلى الله عليه وسلم : إن لي جارين وقد أمرت بإكرام الجار مطلقًا؛ ولا أقدر على الإهداء إليهما معًا، فإلى أيهما أهدي ليحصل لي الدخول في جملة القائمين بإكرام الجار؟ فقال صلى الله عليه وسلم : "إلى أقربهما منك بابًا".', 'استحباب تقديم الجار الأقرب فالأقرب إذا لم يقدر على الإحسان إلى الجميع.
ينبغي مراعاة شعور الجار الأقرب؛ لأنه يرى ما يدخل بيت جاره من هدية وغيرها بخلاف الأبعد، وكذلك هو الأسرع إجابة لما يقع لجاره.
القرب المعتبر هو قرب الأبواب.
يؤخذ من الحديث تقديم العلم على العمل، ولذلك سألت عائشة -رضي الله عنها- عن حكم المسألة قبل المباشرة في الفعل.', 'أقربهما منك باباً : أي: الجار القريب.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4250', false),
(20311, 2, 201, 311, 'hadith', 'عن عبد الله بن عمر رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم: «خير الأصحاب عند الله تعالى خيرهم لصاحبه، وخير الجيران عند الله تعالى خيرهم لجاره».', 'Messenger of Allah (ﷺ) said, "The best of companions with Allah is the one who is best to his companions, and the best of neighbours to Allah is the one who is the best of them to his neighbour"..', 'عبد الله بن عمر رضي الله عنهما', '''Abdullah bin ''Umar (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 311', 'Riyad as-Salihin 311', 'ریاض الصالحین 311', 'رواه الترمذي وقال: حديث حسن', 'خير الأصحاب عند الله منزلة وثواباً أكثرهما نفعاً لصاحبه، و كذلك خير الجيران عند الله أكثرهم نفعاً لجاره.', 'الحث على تحصيل النفع للأصدقاء والجيران والحرص على دفع الأذى عنهم.
الحث على تعظيم الصحبة الإيمانية وتعزيزها.
حرص الإسلام على تقوية أواصر المحبة بين المسلمين.
السعي إلى تحصيل الصاحب الصالح والجار الصالح.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3709', false),
(20312, 2, 201, 312, 'hadith', 'عن أبي عبد الرحمن عبد الله بن مسعود رضي الله عنه قال: سألت النبي صلى الله عليه وسلم : أي العمل أحب إلى الله تعالى؟ قال " الصلاة على وقتها" قلت: ثم أي؟ قال: " بر الوالدين" قلت: ثم أي؟ قال: " الجهاد في سبيل الله".', 'I asked the Prophet (ﷺ) , "Which of the deeds is loved most by Allah?" Messenger of Allah (ﷺ) said, "Salat at its proper time." I asked, ''''What next?" He (ﷺ) replied, ''''Kindness to parents." I asked, ''''What next?" He replied, ''''Jihad in the way of Allah.".', 'أبي عبد الرحمن عبد الله بن مسعود رضي الله عنه', '''Abdullah bin Mas''ud (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 312', 'Riyad as-Salihin 312', 'ریاض الصالحین 312', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20313, 2, 201, 313, 'hadith', 'عَنْ أَبِي هُرَيْرَةَ رضي الله عنه، قَالَ: قَالَ رَسُولُ الله صلى الله عليه وسلم «لاَ يَجْزِي وَلَدٌ وَالِدًا إِلاَّ أَنْ يَجِدَهُ مَمْلُوكًا فَيَشْتَرِيَهُ فَيُعْتِقَهُ».', 'Messenger of Allah (ﷺ) said, "No son can repay (the kindness shown by his father) unless he finds him a slave and buys him and emancipates him"..', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 313', 'Riyad as-Salihin 313', 'ریاض الصالحین 313', 'رواه مسلم', 'لا يقوم ولد بما لأبيه عليه من حق ولا يكافئه بإحسانه به إلا أن يجده مملوكًا فيشتريه ويعتقه.', 'عظيم حق الوالدين في الإسلام.
ظاهر الحديث: أنه لا بد من التصريح بالعتق، ولكن هذا الظاهر غير مراد بل يُعتق الأب على الابن بمجرد الشراء، ولا يحتاج إلى تصريح بالعتق.
إذا اشترى الولد أمه المملوكة عُتقت عليه بمجرد الشراء ولا يحتاج إلى تصريح بالعتق.
لا يجوز للولد أن يسترق أبويه أو أحدهما، فإن حدث ذلك؛ فهو من أمارات الساعة، ودلائل تغيير الزمان.', 'يجزي : يكافئ.
العتق : أعتق العبد: حرره فهو معتق.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3775', false),
(20314, 2, 201, 314, 'hadith', 'وعنه أيضاً أن رسول الله قَالَ : « مَنْ كَانَ يُؤْمِنُ باللهِ وَاليَومِ الآخِرِ ، فَلْيُكْرِمْ ضَيْفَهُ ، وَمَنْ كَانَ يُؤْمِنُ باللهِ وَاليَومِ الآخِرِ ، فَلْيَصِلْ رَحِمَهُ ، وَمَنْ كَانَ يُؤْمِنُ بِاللهِ وَاليَومِ الآخِرِ ، فَلْيَقُلْ خَيْراً أَوْ لِيَصْمُتْ » . مُتَّفَقٌ عَلَيهِ .', 'Messenger of Allah (ﷺ) said, "He who believes in Allah and the Last Day, let him be hospitable to his guest; and he who believes in Allah and the Last Day, let him maintain good the ties of blood relationship; and he who believes in Allah and the Last Day, must speak good or remain silent"..', null, 'Abu Hurairah (May Allah be pleased with him)', null, 'رياض الصالحين 314', 'Riyad as-Salihin 314', 'ریاض الصالحین 314', null, null, null, null, 'sunnah.com', null, false, null, false),
(20315, 2, 201, 315, 'hadith', 'وعنه قال: قال رسول الله صلى الله عليه وسلم : " إن الله تعالى خلق الخلق حتى إذا فرغ منهم قامت الرحم، فقالت: هذا مقام العائذ بك من القطيعة، قال: نعم أما ترضين أن أصل من وصلك، وأقطع من قطعك؟ قالت: بلى، قال: فذلك لك، ثم قال رسول الله صلى الله عليه وسلم : " اقرءوا إن شئتم: (فهل عسيتم إن توليتم أن تفسدوا في الأرض وتقطعوا أرحامكم. أولئك الذين لعنهم الله فأصمهم وأعمى أبصارهم) ((متفق عليه)). وفي رواية للبخاري: فقال الله تعالى: " من وصلك، وصلته، ومن قطعك، قطعته".', 'Messenger of Allah (ﷺ) said, "Allah created all the creatures and when He finished the task of His creation, Ar-Rahm (ties of relationship) said: ''(O Allah) at this place I seek refuge with You against severing my ties.'' Allah said: ''That I treat with kindness those who treat you with kindness and sever ties with those who sever ties with you.'' It said: ''I am satisfied.'' Allah said: ''Then this is yours". Then Messenger of Allah (ﷺ) said, "Recite this Ayah if you like: ''Would you then, if you were given the authority, do mischief in the land, and sever your ties of kinship? Such are they whom Allah has cursed, so that He has made them deaf and blinded their sight". (47:22,23)..The words in Al-Bukhari are: Messenger of Allah (ﷺ) said, "Allah (SWT) says: ''He who maintains good ties with you, I maintain good ties with him; and he who severs your ties, I sever ties with him".', null, 'Abu Hurairah (May Allah be pleased with him)', null, 'رياض الصالحين 315', 'Riyad as-Salihin 315', 'ریاض الصالحین 315', null, null, null, null, 'sunnah.com', null, false, null, false),
(20316, 2, 201, 316, 'hadith', 'وعنه رضي الله عنه قال: جاء رجل إلى رسول الله صلى الله عليه وسلم فقال: يا رسول الله من أحق الناس بحسن صحابتي؟ قال: " أمك" قال: ثم من؟ قال: " أمك" قال: ثم من؟ قال: "أمك" قال: ثم من؟ قال: " أبوك" ((متفق عليه)). وفي رواية: يارسول الله من أحق بحسن الصحبة؟ قال: " أمك، ثم أمك، ثم أمك، ثم أباك، ثم أدناك أدناك".', 'A person came to Messenger of Allah (ﷺ) and asked, "Who among people is most deserving of my fine treatment?" He (ﷺ) said, "Your mother". He again asked, ''''Who next?" "Your mother", the Prophet (ﷺ) replied again. He asked, "Who next?" He (the Prophet (ﷺ)) said again, "Your mother." He again asked, "Then who?" Thereupon he (ﷺ) said," Then your father."In another narration: "O Messenger of Allah! Who is most deserving of my fine treatment?" He (ﷺ) said, "Your mother, then your mother, then your mother, then your father, then your nearest, then nearest"..', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 316', 'Riyad as-Salihin 316', 'ریاض الصالحین 316', null, 'هذا الحديث يدل على أن لكل من الأبوين حقًا في المصاحبة الحسنة؛ والعناية التامة بشؤونه (وصاحبهما في الدنيا معروفًا )، ولكن حق الأم فوق حق الأب بدرجات، إذ لم يذكر حقه إلا بعد أن أكد حق الأم تمام التأكيد، بذكرها ثلاث مرات، وإنما علت منزلتها منزلته مع أنهما شريكان في تربية الولد هذا بماله ورعايته؛ وهذه بخدمته في طعامه وشرابه، ولباسه وفراشه و ... إلخ.
لأن الأم عانت في سبيله ما لم يعانه الأب، فحملته تسعة أشهر وهنًا على وهنٍ، وضعفًا إلى ضعف؛ ووضعته كرهًا؛ يكاد يخطفها الموت من هول ما تقاسي، وكذلك أرضعته سنتين، ساهرة على راحته، عاملة لمصلحته وإن برحت بها في سبيل ذلك الآلام وبذلك نطق الوحي: (ووصينا الإنسان بوالديه إحسانا حملته أمه كرها ووضعته كرها وحمله وفصاله ثلاثون شهرا)، فتراه وصى الإنسان بالإحسان إلى والديه؛ ولم يذكر من الأسباب إلا ما تعانيه الأم إشارة إلى عظم حقها.
ومن حسن المصاحبة للأبوين الإنفاق عليهما طعامًا وشراباً، ومسكناً ولباسًا؛ وما إلى ذلك من حاجات المعيشة، إن كانا محتاجين، بل إن كانا في عيشة دنيا أو وسطى؛ وكنت في عيشة ناعمة راضية فارفعهما إلى درجتك أو زد، فإن ذلك من الإحسان في الصحبة. 
واذكر ما صنع يوسف مع أبويه وقد أوتي الملك إذ رفعهما على العرش بعد أن جاء بهما من البدو. ومن حسن الصحبة بل جماع أمورها ما ذكره الله بقوله: ( وقضى ربك ألا تعبدوا إلا إياه وبالوالدين إحسانا إما يبلغن عندك الكبر أحدهما أو كلاهما فلا تقل لهما أف ولا تنهرهما وقل لهما قولاً كريمًا. واخفض لهما جناح الذل من الرحمة وقل رب ارحمهما كما ربياني صغيرا ) فامنع عنهما لسان البذاءة، وجنبهما أنواع الأذى. وأَلن لهما قولك؛ واخفض لهما جناحك؛ وذلل لطاعتهما نفسك، ورطب لسانك بالدعاء لهما من خالص قلبك وقرارة نفسك وقل: (رب ارحمهما كما ربياني صغيرا)، ولا تنس زيادة العناية بالأم، عملا بإشارة الوحي؛ ومسايرة لمنطق الحديث.', 'عظيم حق الوالدين.
زيادة الوصية بالأم لضعفها وحاجتها.
إكرام ذوي القرابات ليس على درجة واحدة.
ترتيب الحقوق ووضعها في مواضعها هو الأصل والعدل.
تقديم الأم على الأب في النفقة.', 'صحابتي : صحبتي.
ثم أباك : ثم بر أباك.
أدْنَاك أدْنَاك : الأقرب فالأقرب.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4182', false),
(20317, 2, 201, 317, 'hadith', 'وعنه عن النبي صلى الله عليه وسلم قال: « رغم أنف، ثم رغم أنف، ثم رغم أنف من أدرك أبويه عند الكبر، أحدهما أو كليهما، فلم يدخل الجنة».', 'The Prophet (ﷺ) said, "May he be disgraced! May he be disgraced! May he be disgraced, whose parents, one or both, attain old age during his life time, and he does not enter Jannah (by rendering being dutiful to them)"..', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 317', 'Riyad as-Salihin 317', 'ریاض الصالحین 317', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(20318, 2, 201, 318, 'hadith', 'وعنه أن رجلاً قَالَ : يَا رَسُول الله ! إنّ لِي قَرابةً أصِلُهُمْ وَيَقْطَعُوني ، وَأُحْسِنُ إلَيْهِمْ وَيُسِيئُونَ إلَيَّ ، وَأحْلَمُ عَنْهُمْ وَيَجْهَلُونَ عَلَيَّ ، فَقَالَ : « لَئِنْ كُنْتَ كَمَا قُلْتَ ، فَكأنَّمَا تُسِفُّهُمْ الْمَلَّ ، وَلا يَزَالُ مَعَكَ مِنَ اللهِ ظَهِيرٌ عَلَيْهِمْ مَا دُمْتَ عَلَى ذلِكَ ».', 'A man said to Messenger of Allah (ﷺ): "I have relatives with whom I try to keep the ties of relationship but they sever relations with me; and whom I treat kindly but they treat me badly, I am gentle with them but they are rough to me." He (ﷺ) replied, "If you are as you say, it is as if you are feeding them hot ashes, and you will be with a supporter against them from Allah as long as you continue to do so"..', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 318', 'Riyad as-Salihin 318', 'ریاض الصالحین 318', 'رواه مسلم', 'اشتَكَى رَجُلٌ للنبيِّ صلى الله عليه وسلم بأنّ له قرابةً ورَحِمًا يَتَعامَل معهم بالحُسنى وهم يُعامِلونه بضد ذلك؛ فيَصِلُهم ويأتِيْهم وهم يَقْطَعونه، ويُحسن إليهم بالبر والوفاء ويُسيئون إليه بالجَوْر والجَفَاء، ويَحلم ويعفو عنهم ويَجهلون عليه بالقبيح من القول والفعل، فهل يَستَمِرُّ بالصِّلَة لهم مع ما ذُكِر؟ 

فقال له النبيُّ صلى الله عليه وسلم: إنْ كان كما ذَكَرتَ فإنك تُخزِيهم وتَحْقِرُهم في أنفسهم، وكأنك تُطعِمُهم الرَّمَاد الحارّ؛ لكثرة إحسانك وقبيح فِعلِهم عند أنفسهم، ولا يزال معك من عند الله مُعين لك عليهم، ودافِع عنك أذاهم ما دُمْتَ على ما ذَكرتَ من إحسانك إليهم، وظَلُّوا هم على إساءتهم إليك.', 'مقابلة الإساءة بالإحسان مَظِنّة رجوع  المسيء إلى الحق، كما قال تعالى: (ادفع بالتي هي أحسن فإذا الذي بينك وبينه عداوة كأنه ولي حميم).
امتثال أمْر الله ولو حصل له أذى سببٌ لعون الله للعبد المؤمن.
قطيعة الرحم أَلَمٌ وعذابٌ في الدنيا، وإثمٌ وحساب في الآخرة.
ينبغي على المسلم أنْ يَحتَسِب في عمله الصالح، ولا يقطعه أذى الناس وقطيعتُهم عن عادته الطيبة.
ليس الواصلُ لِرَحِمِهِ مَن يُكافِئ مَن وَصَله، ولكن الواصل حقيقة هو الذي إذا قُطِعَتْ رَحِمُه وَصَلَها.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3863', false),
(20319, 2, 201, 319, 'hadith', 'عن أنس رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: « من أحب أن يبسط له في رزقه، وينسأ له في أثره، فليصل رحمه».', 'Messenger of Allah (ﷺ) said, "He who desires ample provisions and his life be prolonged, should maintain good ties with his blood relations".  .', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 319', 'Riyad as-Salihin 319', 'ریاض الصالحین 319', 'متفق عليه', 'يَحُثُّ النبيُّ صلى الله عليه وسلم على صِلة الأقاربِ بالزيارة والإكرام البدني والمالي وغير ذلك، وأنها سببٌ في سَعة الرزق وطول العمر.', 'الرَّحِم هم الأقارب من جهة الأب والأم، وكلما كان أقرب كان أولى بالصلة.
الجزاء من جنس العمل، فمَن وَصَل رَحِمَه بالبر والإحسان، وَصَله الله في عُمْره ورزقه.
صلة الرحم سببٌ لِبَسْطِ الرِّزق وتوسيعه، وسببٌ لطول العمر، وإن كان الأجلُ والرزقُ محددًا إلا أنه قد يكون بركة في الرزق والعمر، فيفعل في عمره أكثر وأنفع مما يفعله غيرُه، وقيل زيادة الرزق والعمر زيادة حقيقية. والله أعلم.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5372', false),
(20320, 2, 201, 320, 'hadith', 'وعنه قال: كان أبو طلحة أكثر الأنصار بالمدينة مالاً من نخل، وكان أحب أمواله إليه بيرحاء، وكانت مستقبلة المسجد، وكان رسول الله صلى الله عليه وسلم يدخلها، ويشرب من ماء فيها طيب، فلما نزلت هذه الآية: {لن تنالوا البر حتى تنفقوا مما تحبون} ((آل عمران: 92)) قام أبو طلحة إلى رسول الله صلى الله عليه وسلم فقال: يا رسول الله إن الله تبارك وتعالى يقول: {لن تنالوا البر حتى تنفقوا مما تحبون} وإن أحب مالي إلي بيرحاء، وإنها صدقة لله تعالى، وأرجو برها وذخرها عند الله تعالى، فضعها يا رسول الله حيث أراك الله. فقال رسول الله صلى الله عليه وسلم: «بخ! ذلك مال رابح، وذلك مال رابح! وقد سمعت ما قلت، وإني أرى أن تجعلها في الأقربين» فقال أبو طلحة: أفعل يا رسول الله، فقسمها أبو طلحة في أقاربه وبني عمه. ((متفق عليه)). وسبق بيان ألفاظه في: باب الإنفاق مما يحب.', 'Abu Talhah (May Allah be pleased with him) was the richest among the Ansar of Al-Madinah and possessed the largest property; and among his possessions what he loved most was his garden known as Bairuha'' which was opposite the mosque, and Messenger of Allah (ﷺ) often visited it and drank from its fresh water. When this ayah was revealed: "By no means shall you attain Al-Birr (piety, righteousness - here it means Allah''s reward, i.e., Jannah), unless you spend (in Allah''s Cause) of that which you love," (3:92). Abu Talhah came to Messenger of Allah (ﷺ), and said: "Allah says in His Book: ''By no means shall you attain Al-Birr, unless you spend (in Allah''s Cause) of that which you love,'' and the dearest of my property is Bairuha'' so I have given it as Sadaqah (charity) for Allah''s sake, and I anticipate its reward with Him; so spend it, O Messenger of Allah, as Allah guides you". Messenger of Allah (ﷺ) said, "Well-done! That is profitable property. I have heard what you have said, but I think you should spend it on your nearest relatives." So Abu Talhah distributed it among his nearest relatives and cousins..', null, 'Anas (May Allah be pleased with him)', null, 'رياض الصالحين 320', 'Riyad as-Salihin 320', 'ریاض الصالحین 320', null, null, null, null, 'sunnah.com', null, false, null, false)
